WITH payload AS (SELECT $archive_payload$[{"id":"1690391d-f1b0-5057-b203-771c5a47fc03","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -رجوع عن اإلقرار بالتعاطي -تدرأ احلدود بالشبهات -إدانة -تعزير للتهمة القوية -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد","document_number":"343884","case_number":"32304970","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/05","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -رجوع عن اإلقرار بالتعاطي -تدرأ احلدود بالشبهات -إدانة -تعزير للتهمة القوية -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 343884 :‬تاريخه‪1434/01/05 :‬هـ‬\n                  ‫رقم الدعوى‪32304970:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪ 33458676‬تاريخه ‪1434/01/25 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬رجــوع عــن‬\n‫اإلقــرار بالتعاطــي‪ -‬تــدرأ احلــدود بالشــبهات ‪ -‬إدانــة‪ -‬تعزيــر للتهمــة‬\n‫القويــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر بالســجن واجللــد‬\n                                                                 ‫واإلبعــاد ‪.‬‬\n\n\n\n\n‫املــواد (‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                         ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإثبــات إدانتــه بحيــازة احلشــيش‬\n‫املخــدر لالســتعمال الشــخصي واســتعماله لــه ‪ ،‬واحلكــم عليــه بعقوبــة‬\n‫الســجن واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة حيــث إنــه مت تفتيــش املدعــى عليــه شــخصيا بعــد‬\n‫االشــتباه بــه فعثــر يف حذائــه علــى قطعــة مــن احلشــيش املخــدر وأثبــت‬\n‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش‬\n‫املخــدر‪ ،‬اعتــرف حتقيق ـ ًا بحيازتــه للقطعــة املضبوطــة وأنــه يتعاطــى‬\n‫احلشــيش املخــدر‪ ،‬أنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي العــام‬\n‫ورجــع عــن إقــراره‪ ،‬اســتخلفت احملكمــة ناظــرة الدعــوى احملكمــة‬\n\n                                                                                   ‫‪232‬‬\n\f      ‫التــي يقيــم يف نطــاق اختصاصهــا شــهود محضــر القبــض يف ســماع‬\n      ‫شــهادتهم فشــهدوا مبــا يثبــت دعــوى املدعــي العــام‪ ،‬نظــر ًا لعــدم وجــود‬\n      ‫ســوابق والكميــة احملــازة قليلــة ‪ ،‬فقضــت احملكمــة بإدانــة املدعــى‬\n      ‫عليــه مبــا نســب إليــه وقــررت ســجنه ملــدة أربعــة أشــهر وإبعــاده عــن البالد‬\n      ‫بعــد انتهــاء محكوميتــه كمــا قــررت تعزيــره باجللــد تســع وســبعني‬\n      ‫جلــدة دفعــة واحــدة لتوجــه التهمــة القويــة لــه باســتعمال احلشــيش املخــدر‬\n      ‫واحلبــوب احملظــورة ‪ ،‬عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‬\n                           ‫وقــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ففــي يــوم‬\n      ‫األحــد بتاريــخ ‪1433/5/16‬ه ـ لــدي أنــا‪ ........‬القاضــي باحملكمــة‬\n      ‫اجلزئيــة بنجــران والقائــم بعمــل املكتــب القضائــي الرابــع بنــاء علــى‬\n      ‫املعاملــة املقيــدة باحملكمــة برقــم ‪ 32933484‬وتاريــخ ‪1432/7/23‬ه ـ‬\n      ‫واحملالــة باإلحالــة رقــم ‪ 32304970‬وتاريــخ ‪1433/7/23‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــر وعليــه فقــد حضــر املدعــي العــام ‪........‬‬\n      ‫بخطــاب تعميــد رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام بنجــران رقــم‬\n      ‫‪ ........‬وتاريــخ ‪1430/2/29‬ه ـ وحضــر حلضــوره املدعــى عليــه ‪................‬‬\n      ‫مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬وقــد ادعــى املدعــي‬\n      ‫العــام قائــا ورد مبحضــر القبــض أنــه بتاريــخ ‪1432/2/25‬ه ـ وأثنــاء‬\n      ‫قيــام الفرقــة بالعمــل امليدانــي للبحــث عــن املطلوبــن واملروجــن ويف متــام‬\n      ‫ـاء مت االشــتباه يف ســيارة مــن نــوع ‪.....‬‬ ‫الســاعة اخلامســة والنصــف مسـ ً‬\n      ‫اللــون أزرق رقــم اللوحــة (‪ )........‬يســتقلها شــخص واحــد متوقفــة بجــوار‬\n\n‫‪233‬‬\n\f‫الطريــق بالقــرب مــن العمــود وعنــد مالحظتــه ســيارة الدوريــة ظهــرت‬\n‫عليــه عالمــات االرتبــاك فتــم النــزول عليــه مــن قبــل الفرقــة وطلــب‬\n‫إثباتــه واتضــح أنــه املدعــى عليــه وبتفتيشــه شــخصي ًا لــم يعثــر معــه يف‬\n‫جيوبــه علــى أي شــيء مــن املمنوعــات وعندمــا طلــب منــه نــزع حذائــه‬\n‫الــذي يرتديــه قــام مبقاومــة الفرقــة مقاومــة عنيفــة وقــام بإخــراج شــيء‬\n‫مــن احلــذاء وابتالعــه فتــم الســيطرة عليــه وضبــط مــا بقــي داخــل احلــذاء‬\n‫وكان عبــارة عــن ورقــه بداخلهــا فرطــة ســجائر يشــتبه أن تكــون‬\n‫مخلوطــة مبــادة احلشــيش املخــدر وعلــى قطعــة ســمراء ملصقــة باحلــذاء‬\n‫مــن الداخــل يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر وعلــى منديــل‬\n‫أبيــض بداخلــه حبــه بيضــاء اللــون حتمــل العالمــة املميــزة للكبتاجــون‬\n‫يشــتبه أن تكــون مــن احلبــوب احملظــورة فتــم القبــض علــى املذكــور‬\n‫وبتفتيــش ســيارته لــم يعثــر بداخلهــا علــى أي شــيء مــن املمنوعــات فتــم‬\n‫إيداعــه التوقيــف رهــن التحقيــق وإجــراء الــازم حيــال ذلــك ومت إعــداد‬\n‫هــذا احملضــر حفاظ ـ ًا للواقــع واهلل املوفــق علم ـ ًا بــأن املقاومــة كانــت‬\n‫محاولــة منــه البتــاع املضبوطــات‪ .‬وقــد اثبــت التقريــر الكيميائــي‬\n‫الشــرعي الصــادر مــن مركــز املراقبــة والســموم مبنطقــة تبــوك رقــم‬\n‫(‪ )........‬أن العينــة املرســلة بالرقــم الســري(‪)........‬إيجابية للحشــيش‬\n‫املخــدر‪ .‬وأن العينــة املرســلة بالرقــم الســري (‪ )........‬واحملتويــة علــى حبــة‬\n‫واحــدة تبــن ســلبيتها العينــة أي مــادة مشــتبهة‪ .‬وباســتجواب املدعى عليه‬\n‫أقــر بأنــه مت القبــض عليــه وعثــر بحذائــه الــذي بقدمــه علــى عــدد حبــة‬\n‫واحــده مــن احلبــوب احملظــورة وكذلــك ســيجارة مخلوطــة باحلشــيش‬\n‫املخــدر وأنــه يتعاطــى احلشــيش املخــدر واحلبــوب احملظــورة منــذ حوالــي‬\n‫شــهر‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بحيــازة قطعــة‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪9‬ملجــم) لغــرض االســتعمال الشــخصي‬\n      ‫ال‬‫واســتعماله املســبق للحشــيش املخــدر وللحبــوب احملظــورة ممــا يعــد فع ً‬\n      ‫مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n      ‫وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة‪ .1 :‬إقــراره حتقيق ًا‬\n      ‫املنــوه عنــه واملــدون علــى ص(‪ )5‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪.)1‬‬\n      ‫‪ .2‬محضــر القبــض والتفتيــش املنــوه عنــه واملــدون علــى ص(‪ )1‬لفــة رقــم‬\n      ‫(‪ .3.)1‬التقريــر الكيميائــي الطبــي الشــرعي املنــوه عنــه املرفــق لفــة (‪.)6‬‬\n      ‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجله‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم شــرع ًا ومجــرم ومعاقــب عليــه نظام ـ ًا لــذا أطلــب‬\n      ‫إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪ .1 :‬العقوبــة الــواردة‬\n      ‫يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات املنــوه‬\n      ‫عنــه‪ .2 .‬ابعــاده عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‬\n      ‫وال يســمح لــه بالعــودة إليهــا ‪ ،‬فيمــا عــدا مــا تســمح بــه تعليمــات احلــج‬\n      ‫والعمــرة اســتناد ًا للفقــرة الثانيــة مــن املــادة (‪ )56‬السادســة واخلمســن من‬\n      ‫النظــام ذاتــه‪ .‬هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n      ‫عليــه اجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي قطعــة‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪9‬ملجــم) لغــرض االســتعمال الشــخصي‬\n      ‫واســتعمالي يف الســابق للحشــيش املخــدر واحلبــوب احملظــورة هــذا غيــر‬\n      ‫صحيــح والصحيــح اننــي كنــت اســير بســيارتي وهــي مســتأجرة ليســت‬\n      ‫ملــكا لــي واســتوقفوني وقامــوا بتفتيشــي ولــم يعثــروا معــي علــى اي‬\n      ‫شــيء ومــن ثــم ذهبــت معهــم الــى املركــز واخبرونــي انهــم وجــدوا معــي‬\n\n\n‫‪235‬‬\n\f‫هــذه القطعــة مــن احلشــيش وانــا ليــس لــي علــم بهــا وال تعــود لــي هــذه‬\n‫اجابتــي وبســؤال املدعــي العــام قــال غيــر صحيــح والصحيــح مــا ذكرت‬\n‫وبســؤاله هــل لديــك بينــه علــى مــا جــاء يف دعــواك قــال بينتــي مــا جــاء يف‬\n‫اوراق املعاملــة ثــم جــرى منــي االطــاع علــى محضــر القبــض والتفتيــش‬\n‫واملنــوه عنــه واملــدون علــى (ص‪)1‬لفــة رقــم (‪ )1‬وافهمــت املدعــي العــام‬\n‫بإحضارهــا يف اجللســة القادمــة ثــم قــرر املدعــي العــام بــأن افــراد الفرقــة‬\n‫خــارج املنطقــة وانهــم يف محافظــة ‪ ........‬ويطلــب اســتخالف احملكمــة‬\n‫التــي يف نطــاق تواجدهــم لســماع شــهادتهم فقــررت بنــاء علــى ذلــك‬\n‫اســتخالف محكمــة ‪ ........‬لســماع شــهادة افــراد الفرقــة وارســال‬\n‫صــورة مــن الضبــط ملــا دون مــن شــهادتهم ثــم رفعــت اجللســة حتــى ورود‬\n‫البينــة وبــاهلل التوفيــق حــرر يف ‪1433/5/16‬ه ـ الســاعة احلاديــة عشــر‬\n‫والنصــف ففــي يــوم األربعــاء املوافــق ‪ 1433/8/14‬ه ـ فتحــت اجللســة‬\n‫الثانيــة وفيهــا حضــر املدعــي العــام كمــا حضــر املدعــى عليــه وقــد‬\n‫عــادت لنــا املعاملــة وبرفقهــا صــورة مــن ضبــط شــهادة أفــراد الفرقــة‬\n‫الــواردة إلينــا مــن احملكمــة العامــة ب ـ ‪ ........‬وباالطــاع عليهــا وجدنــا مــا‬\n‫نصــه ( احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي مبحكمــة ‪........‬‬\n‫العامــة ففــي يــوم الســبت املوافــق ‪1433/6/21‬ه ـ افتتحــت اجللســة بنــاء‬\n‫علــى املعاملــة الــواردة لنــا مــن رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n‫‪ 33930740‬يف ‪1433/5/17‬ه ـ املتضمــن اســتخلفنا يف ســماع بينــة‬\n‫املدعــي العــام وتزكيتهــا ضــد ‪........‬مينــي اجلنســية يف قضيــة مخــدرات‬\n‫وعليــه فقــد حضــر اجلنــدي ‪ ........‬ســعودي بالســجل رقــم ‪ ........‬واجلنــدي‬\n‫‪ ........‬ســعودي بالســجل رقــم ‪ ........‬واجلنــدي ‪ ........‬ســعودي بالســجل رقــم‬\n‫‪ ........‬وقــد جــرى عــرض احملضــر املرفــق باملعاملــة فشــهد كل واحــد‬\n\n\n                                                                                         ‫‪236‬‬\n\f      ‫منهــم مبفــرده قائــا اشــهد بــاهلل العظيــم بــأن مــا ورد مبحضــر القبــض‬\n      ‫بتاريــخ ‪1432/2/25‬ه ـ املذكــور كلــه صحيــح جملــة وتفصيال هكذا‬\n      ‫شــهدوا فطلبــت منهــم احضــار معدلــن لهــم فحضــر ‪........‬و‪ ........‬وأجــاب‬\n      ‫كل واحــد منهــم بــأن الشــهود ثقــات عــدول مقبولــي الشــهادة وعليــه‬\n      ‫قــررت بعــث صــورة الضبــط إلــى رئيــس احملكمــة اجلزائيــة بنجــران رفــق‬\n      ‫املعاملــة وانتهــت اجللســة يف متــام الســاعة احلاديــة والنصــف وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد الشــاهد ‪ ........‬توقيعــه الشــاهد‪ ........‬توقيعــه‬\n      ‫الشــاهد ‪ ........‬توقيعــه الكاتــب ‪ ........‬توقيعــه املزكــي ‪ ........‬توقيعــه‬\n      ‫املزكــي ‪ ................‬توقيعــه القاضــي ‪ ........‬توقيعــه وختمــه) وبعــرض‬\n      ‫شــهادة الشــهود علــى املدعــى عليــه قــال غيــر صحيــح جملــة وتفصيــا‬\n      ‫ثــم جــرى منــا االطــاع علــى دفتــر التحقيــق املرفــق باملعاملــة لفــة (‪)1‬‬\n      ‫ص (‪ )3‬فوجدنــا إقــرار املدعــى عليــه حتقيقــا بأنــه مت العثــور داخــل‬\n      ‫حذائــه الــذي بقدمــه علــى عــدد حبــة واحــدة محظــورة وكذلــك قطعــة‬\n      ‫حشــيش مخــدر وهــي عائــده لــه شــخصيا لالســتخدام الشــخصي وقــد‬\n      ‫تعاطــى حبــة واحــدة وكذلــك ســيجارة مخلوطــة باحلشــيش املخــدر وأنــه‬\n      ‫يتعاطــى احلشــيش املخــدر واحلبــوب احملظــورة مــن ثــاث أشــهر تقريبــا‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه قــال غيــر صحيــح وقــد وقعــت علــى‬\n      ‫ذلــك بعــد أن وعــدت باخلــروج وإنهــاء القضيــة هــذه إجابتــي ثــم جــرى منــا‬\n      ‫االطــاع علــى التقريــر الكيميائــي الشــرعي رقــم فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وحيــث أنكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n      ‫املدعي العام وبناء عل ـ ــى مـ ــا شهـ ــدت بـ ــه البينة املعدلة شرعـ ــا وم ــا ورد‬\n      ‫يف إق ــراره حتقـيـق ـ ًا وبن ــاء عل ــى قل ــة الكـمـي ــة الـمـضـبـوط ــة وبـنـاء عـلــى‬\n      ‫الـم ــادة (‪ )60 ، 56 ، 41‬مــن نظــام املخــدرات وبنــاء علــى عــدم وجــود‬\n\n\n‫‪237‬‬\n\f‫ســوابق جنائيــة علــى املدعــى عليــه فقــد قــررت مــا يلــي‪ /1 :‬ثبــت لــدي‬\n‫إدانــة املدعــى عليــه بح ــيازة لقط ـع ــة مــن احلشيـ ــش الـمـخـ ــدر بلـ ــغ وزنـهـ ــا‬\n‫(‪ 9‬جــم) تســعة جرامــات بقصــد االســتخدام الشــخصي وحيــازة حبــة‬\n‫واحــدة مــن احلبــوب احملظــورة بقصــد االســتخدام الشــخصي وحكمــت‬\n‫بســجنه ملــدة أربعــة أشــهر يحســب منهــا مــن تاريــخ إيقافــه ‪/2‬توجيــه‬\n‫التهمــه القويــة للمدعــى عليــه باســتعماله يف الســابق للحشــيش املخــدر‬\n‫وتعاطيــه للحبــوب احملظــورة وحكمــت بتعزيــره لقــاء ذلــك وذلــك بجلــده‬\n‫تســعة وســبعني جلــدة دفعــة واحــدة ‪/3‬إبعــاد املدعــى عليــه مــن البــاد بعد‬\n‫انتهــاء محكوميتــه وال يســمح لــه بالدخــول إال فيمــا تقتضيــه تعليمــات‬\n‫احلــج والعمــرة وبعــرض ذلــك علــى املدعــي العــام و املدعــى عليــه قــرر‬\n‫املدعــى عليــه اعتراضــه علــى احلكــم بالئحــة فأجبتــه لطلبــه وأفهمتــه‬\n‫بــأن عليــه مراجعــة احملكمــة يف يــوم األحــد بتاريــخ ‪1433/8/18‬ه ـ‬\n‫الســتالم صــورة مــن القــرار الشــرعي لالعتــراض عليــه خــال مــدة‬\n‫شــهر مــن تاريــخ اســتالم صــورة القــرار وإذا لــم يقــدم اعتراضــه علــى‬\n‫احلكــم ســقط حقــه يف االعتــراض ومــن ثــم رفــع كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n‫بــدون الئحــة اعتراضيــة وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                        ‫‪1433/8/14‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/1/5‬ه ـ افتتحــت‬\n‫اجللســة وقــد عــادت لنــا املعاملــة مــن محكمــة االســتئناف بعســير‬\n‫بكتــاب فضيلــة رئيســها برقــم ‪ 331892599‬وتاريــخ ‪1433/11/27‬ه ـ‬\n‫واملقيــدة بهــذه احملكمــة برقــم ‪ 332189628‬وتاريــخ ‪1433/12/19‬ه ـ‬\n‫وبرفقهــا القــرار الصــادر بشــأنها مــن الدائــرة الرابعــة لتدقيــق القضايــا‬\n\n\n                                                                                               ‫‪238‬‬\n\f      ‫اجلزائيــة برقــم ‪ 33458676‬وتاريــخ ‪1433/11/20‬ه ـ ونصــه بعــد‬\n      ‫املقدمــة (وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة تقــرر باألكثريــة إعادتهــا لفضيلــة حاكمهــا ملالحظــة‬\n      ‫مــا يلــي‪ :‬أوال‪ /‬أن فضيلــة ناظــر القضيــة لــم يعــرض الشــهود وحالهــم‬\n      ‫وشــهادتهم علــى املدعــى عليــه وال بــد مــن ذلــك‪ .‬ثانيــا‪ /‬وجــود أخطــاء‬\n      ‫إمالئيــة اشــير حتتهــا بقلــم الرصــاص ينبغــي تصحيحهــا فعلــى فضيلتــه‬\n      ‫مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق ) أ ه ـ وعليــه أجيــب‬\n      ‫أصحــاب الفضيلــة أن مــا جــاء ذكــره يف املالحظــة األولــى فقــد جــرى‬\n      ‫منــي عــرض شــهادة الشــهود وحالهــم علــى املدعــى عليــه وأنكــر صحــة‬\n      ‫شــهادتهم جملــة وتفصيــا كمــا ثبــت ذلــك يف الضبــط وأمــا مــا جــاء يف‬\n      ‫املالحظــة الثانيــة فســيتم تعديــل ذلــك وإكمــال الــازم واهلل يحفظكــم‬\n      ‫ويرعاكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى ســيدنا محمــد حــرر‬\n                                                                ‫يف ‪1434/1/5‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n      ‫‪ 332189628‬وتاريــخ ‪1434/1/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...../‬برقــم ‪ 33399354‬وتاريــخ‬\n      ‫‪1433/09/02‬هـ اخلاص بدعوى املدعي العام ضد ‪ .... /‬ميني اجلنسية‪،‬‬\n      ‫يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n      ‫ـاء علــى قرارنــا رقــم‬\n                           ‫حكــم فضيلتــه وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n      ‫(‪ )33458676‬وتاريــخ ‪1433/11/20‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد االجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n‫‪239‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":232,"source_page_end":239,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d1505497ec9b986a708b3958f4153e4d99dc651748e386e207b1efc7ff9ffd5d","normalized_text_hash":"2afce884a3bda3e21c7ba8b693f202f6cf9e5763a74fa4f8e018c20c0da005d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p232-343884"},{"id":"8771cc7a-5ce0-5bde-a5a9-fed185799048","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي -عدم قبول الرجوع عن اإلقرار فيما موجبه التعزير -إدانة -انقضاء الدعوى العامة بالوفاة -تعزير املدعى عليه احلاضر بالسجن واملنع من السفر.","document_number":"34272983","case_number":"32901007","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/14","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي -عدم قبول الرجوع عن اإلقرار فيما موجبه التعزير -إدانة -انقضاء الدعوى العامة بالوفاة -تعزير املدعى عليه احلاضر بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34272983:‬تاريخه‪1433/11/14 :‬هـ‬\n                     ‫رقم الدعوى‪32901007:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34272983‬تاريخه ‪1434/07/18 :‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‪ -‬عــدم‬\n ‫قبــول الرجــوع عــن اإلقــرار فيمــا موجبــه التعزيــر‪ -‬إدانــة‪ -‬انقضــاء‬\n ‫الدعــوى العامــة بالوفــاة ‪ -‬تعزيــر املدعــى عليــه احلاضــر بالســجن‬\n                                                       ‫واملنــع مــن الســفر‪.‬‬\n\n\n\n\n ‫‪ -1‬جــاء يف الشــرح الكبيــر (‪« :)30/222‬وال يقبــل رجــوع املقــر عــن‬\n                                                                 ‫إقــراره‪ ..‬إلــخ»‪.‬‬\n ‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬و الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهمــا تتضمــن طلــب إثبــات إدانتهمــا‬\n ‫بحيــازة احلشــيش املخــدر وحيــازة األول حلبــة مــن حبــوب اإلمفيتامــن‬\n ‫بقصــد التعاطــي‪ ،‬واحلكــم عليهمــا بعقوبــة الســجن واملنــع مــن الســفر‬\n ‫طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعلــى األول‬\n ‫باملقتضــى الشــرعي لقــاء التعاطــي‪ ،‬مت تفتيــش الســيارة التــي يقودهــا‬\n ‫املدعــى عليــه الثانــي فعثــر فيهــا علــى ســيجارتني مــن احلشــيش املخــدر‬\n ‫ومت تفتيــش األول شــخصيا فعثــر بجيبــه علــى حبــة يشــتبه أن تكــون‬\n\n                                                                                      ‫‪240‬‬\n\f      ‫محظــورة‪ -‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n      ‫للحشــيش املخــدر واإلمفيتامــن‪ ،‬املدعــى عليــه األول تــويف مبوجــب‬\n      ‫شــهادة الوفــاة الصــادرة مــن اجلهــة املختصــة‪ ،‬اعتــرف الثانــي أمــام جهــة‬\n      ‫التحقيــق بحيازتــه للحشــيش املخــدر بقصــد التعاطــي‪ ،‬أنكــر أمــام‬\n      ‫احملكمــة مــا أســنده إليــه املدعــي العــام ورجــع عــن إقــراره حتقيقا‪،‬مــن‬\n      ‫املقــرر شــرع ًا أن حقــوق اهلل تعالــى التــي ال تــدرأ بالشــبهة ال يقبــل فيهــا‬\n      ‫الرجــوع عــن اإلقــرار بــا خــاف‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه‬\n      ‫الثانــي مبــا نســب إليــه وقــررت ســجنه ملــدة ســتة أشــهر ومنعــه مــن الســفر‬\n      ‫خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض املدعــى عليــه علــى احلكــم ولــم‬\n      ‫يعــارض املدعــي العــام‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                                ‫احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بتبــوك برقــم ‪ 32901007‬وتاريــخ ‪ 1433/11/14‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 3261306‬وتاريــخ ‪1432/01/22‬ه ـ ففــي يــوم الثالثاء‬\n      ‫املوافــق ‪1434/07/18‬ه ـ حضــر املدعــي العــام ‪ ........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ........‬واملعمــد مــن مرجعــه مبوجــب اخلطــاب‬\n      ‫رقــم ‪ 13058‬يف ‪1433/9/5‬ه ـ وحضــر حلضــوره املدعــى عليــه الثانــي‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬ولــم يحضــر‬\n      ‫املدعــى عليــه األول وقــد وردنــا مــن مكافحــة املخــدرات مبنطقــة تبــوك‬\n      ‫صــوره مصدقــه لشــهادة وفــاة حتمــل رقــم ‪ .....‬للمدعــى عليــه األول‬\n\n‫‪241‬‬\n\f‫وبالرجــوع للمعاملــة وجــد أنهــا مشــتملة علــى الئحــة دعــوى عامــة ضــد‬\n‫املذكوريــن وفيهــا أنــه بتاريــخ ‪1431/04/19‬ه ـ ورد باحملضــر املعــد مــن‬\n‫قبــل قيــادة أمــن الطــرق مبنطقــة تبــوك أنــه أثنــاء قيامهــم بعملهــم املعتــاد‬\n‫وتواجدهــم بالنقطــة املتمركــزة علــى طريــق ‪ .....‬مت اســتيقاف ســيارة‬\n‫مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم‪ .....‬يســتقلها شــخصني الســائق ويدعــى‬\n‫‪ ........‬وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى أي شــيء ممنــوع والراكــب‬\n‫ويدعــى ‪ ........‬وبتفتيشــه شــخصي ًا عثــر يف جيبــه األميــن مــن ثوبــه علــى‬\n‫حبــة يشــتبه أن تكــون محظــورة وعلــى قطعــة يشــتبه أن تكــون مــن‬\n‫احلشــيش املخــدر بلــغ وزنهــا اإلجمالــي (‪ 1,800‬ملجــم) جــرام وثمــان‬\n‫مائــة مليجــرام وبتفتيــش الســيارة عثــر يف املرتبــة األمامية بجــوار (القير)‬\n‫علــى علبــة ســجائر عثــر بداخلهــا علــى عــدد(‪ )2‬ســيجارتني ملفوفتــن‬\n‫يشــتبه أن تكونــا مخلوطتــن باحلشــيش املخــدر بلــغ وزنهــا اإلجمالــي‬\n‫(‪2,100‬ملجــم) جرامــان ومائــة مليجــرام فتــم القبــض عليهــم وتســليهم‬\n‫لــإدارة العامــة ملكافحــة املخــدرات وقــد أثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم(‪1009‬م‪/‬م س ت) لعــام ‪1431‬ه ـ الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بصحــة تبــوك إيجابيــة‬\n‫العينة املرسلة للتحليل للحشيش املخدر وهو من املواد املخدرة اخلاضعة‬\n‫للرقابــة واملنــوه عنــه باجلــدول األول فئــة (أ) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ وإيجابيــة العينــة املرســلة للتحليــل لإلمفيتامــن‬\n‫املنبــه للجهــاز العصبــي املركــزي وهــو مــن املؤثــرات اخلاضعــة للرقابــة‬\n‫واملنــوه عنــه باجلــدول الثانــي فئــة(ب) امللحــق بنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة وقــد أســفر التحقيــق معهمــا عــن اتهــام ألول بحيازتــه‬\n\n\n                                                                                        ‫‪242‬‬\n\f      ‫حلبــة واحــدة مــن حبــوب اإلمفيتامــن املنبــه احملظــور ولقطعــة مــن‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا اإلجمالي(‪1,800‬ملجــم) جــرام وثمــان مائــة‬\n      ‫مليجــرام بقصــد التعاطــي وتعاطيــه الســابق للحشــيش املخــدر واتهــام‬\n      ‫الثانــي بحيازتــه لســيجارتني ملفوفتــن مخلوطتــن باحلشــيش املخــدر‬\n      ‫بلــغ وزنهــا اإلجمالــي (‪2,100‬ملجــم) جرامــان ومائــة مليجــرام بقصــد‬\n      ‫التعاطــي وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم شــرع ًا‬\n      ‫ومعاقــب عليــه ونظام ـ ًا اســتناد ًا للمــادة الثالثــة فقرة(الثانيــة) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلب‪-1‬إثبــات مــا أســند إليهمــا‬\n      ‫‪ -2‬احلكــم عليهمــا بالســجن لقــاء مــا أســند إليهمــا اســتناد ًا للمــادة (‪)41‬‬\n      ‫فقــرة(‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه‬\n      ‫أعــاه ‪ -3‬احلكــم مبنعهمــا مــن الســفر اســتناد ًا للمــادة (‪ )56‬فقــرة(‪)1‬‬\n      ‫مــن النظــام املشــار إليــه أعــاه ‪ -4‬احلكــم علــى املدعــى عليــه األول‬\n      ‫باملقتضــى الشــرعي لقــاء تعاطيــه الســابق للحشــيش املخــدر هكــذا‬\n      ‫ادعــى وبســؤال املدعــى عليــه الثانــي عــن الدعــوى أجــاب بقولــه مــا‬\n      ‫جــاء يف دعــوى املدعــي العــام مــن القبــض علينــا ووجــود املضبوطــات يف‬\n      ‫الســيارة التــي كنــت أقودهــا كلــه صحيــح ولكــن مــا مت ضبطــه مــن‬\n      ‫ســيجارتني مخلوطتــن باحلشــيش املخــدر داخــل علبــة الســجائر املوجــودة‬\n      ‫بجــوار ناقــل احلركــة ليســت لــي وإمنــا هــي لصاحبــي ‪ ......‬رحمــه اهلل‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام أجــاب بقولــه الصحيــح‬\n      ‫مــا جــاء يف دعــواي هكــذا قــرر وبطلــب البينــة منــه قــال بينتــي مــا جــاء‬\n      ‫يف الئحــة الدعــوى وأوراق املعاملــة وبالرجــوع إلــى محضــر االســتجواب‬\n      ‫املــدون علــى الصفحــة التاســعة مــن اللفــة الثانيــة عشــر وجــدت فيــه‬\n\n\n‫‪243‬‬\n\f‫اعترافــا منســوب للمدعــى عليــه وفيــه أن الســيجارتني املضبوطتــن‬\n‫داخــل علبــة الســجائر عائــدة لــه وعليــه توقيــع بالبصمــة منســوب إليــه‬\n‫وبعرضــه عليــه أجــاب بقولــه صحيــح أننــي اعترفــت بحيازتــي لهاتــن‬\n‫الســيجارتني بقصــد التعاطــي لــدى هيئــة التحقيــق واالدعــاء العــام مــن‬\n‫أجــل أن يخــرج صاحبــي مــن الســجن هكــذا أجــاب فنظــر ًا إلــى مــا دون‬\n‫مــن الدعــوى واإلجابــة وبعــد االطــاع علــى التقريــر الكيميائــي املشــار‬\n‫إليــه وإلقــرار املدعــى عليــه بوجــود الســيجارتني املخلوطتــن باحلشــيش‬\n‫املخــدر داخــل علبــة الســجائر يف ســيارته وملــا جــاء يف إقــراره حتقيقـ ًا مــن‬\n‫أنهمــا عائدتــان لــه وأن القصــد مــن حيازتهمــا التعاطــي ونظــر ًا إلنــكاره‬\n‫يف مجلــس احلكــم أنهمــا لــه وملــا قــرره أهــل العلــم رحمهــم اهلل مــن أن‬\n‫الرجــوع عــن اإلقــرار يف غيــر احلــدود ال يقبــل قــال يف الشــرح الكبيــر‬\n‫‪(( :222/30‬فصــل‪ :‬وال يقبــل رجــوع املقــر عــن إقــراره إال فيما كان حد ًا‬\n‫هلل تعالــى يــدرأ بالشــبهات ويحتــاط إلســقاطه فأمــا حقــوق اآلدميــن‬\n‫وحقــوق اهلل تعالــى التــي ال تــدرأ بالشــبهات كالــزكاة والكفــارات‬\n‫فــا يقبــل رجوعــه عنهــا‪ .‬وال نعلــم فيــه خالفـاً)) أ‪.‬ه ـ وملــا جــاء يف الفقــرة‬\n‫األولــى مــن املــادة احلاديــة واألربعــن والفقــرة األولــى مــن املــادة السادســة‬\n‫واخلمســن وبنــاء علــى جميــع مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه‬\n‫بحيازتــه لســيجارتني مخلوطتــن باحلشــيش املخــدر بلــغ وزنهــا جرامــان‬\n‫ومائــة مليجــرام لغــرض االســتعمال والتعاطــي وقــررت تعزيــره مبــا يلــي‬\n‫أو ًال حبــس املدعــى عليــه ملــدة ســتة أشــهر يحتســب منهــا فتــرة إيقافــه‬\n‫علــى ذمــة القضيــة ثاني ـ ًا منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n‫ملــدة ســنتني تبــدأ مــن تاريــخ انتهــاء محكوميتــه يف البنــد أو ًال ومبا ذكر‬\n‫حكمــت وبعرضــه علــى املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام‬\n\n\n                                                                                         ‫‪244‬‬\n\f      ‫قناعتــه بــه أمــا املدعــى عليــه فطلــب متييــز احلكــم مســببا ذلــك بــأن مــا‬\n      ‫مت ضبطــه يف ســيارته ليــس لــه أي عالقــة بــه فأجبتــه لطلبــه وســيتم‬\n      ‫بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n      ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/07/18‬ه ـ ‪.‬‬\n      ‫احلمــد اهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة‬\n      ‫يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة مــن‬\n      ‫احملكمــة اجلزائيــة بتبــوك برقــم ‪ 341740956‬وتاريــخ ‪1434/07/24‬هـ‬\n      ‫املرفــق بهــا القــرار رقــم ‪ 34272983‬وتاريــخ ‪1434/07/18‬ه ـ الصــادر‬\n      ‫مــن فضيلــة القاضــي ‪ .....‬اخلــاص بدعــوى املدعــي العــام ضــد ‪ .....‬يف‬\n      ‫قضيــة مخــدرات علــى النحــو املوضــح يف القــرار واملتضمــن حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى أن‬\n      ‫يقــرر انقضــاء الدعــوى العامــة ضــد املدعــى عليــه ‪.....‬لوفاتــه قبــل بعــث‬\n      ‫املعاملــة للتنفيــذ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                         ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪245‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":240,"source_page_end":245,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"baa5b19b19f403027755b44e5fcc89baf9be6fd9ba88c619460f97496a1e71d3","normalized_text_hash":"91ab60c99a8c089cd88d8f1b38c6ee6f68631aa486bed7fb541f376ac75a9873","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p240-34272983"},{"id":"e30b5da3-4fee-546e-8f48-4b81fdc0baf1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -مخدرات -حيازة مسكر -حيازة حشيش بقصد التعاطي والترويج -حيازة حبوب محظورة -سجائر حشيش -إقرار -ثبوت إدانة -حد املسكر -تعزير باجللد والسجن والغرامة واملصادرة واملنع من السفر.","document_number":"33475549","case_number":"33204824","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"مسكر -مخدرات -حيازة مسكر -حيازة حشيش بقصد التعاطي والترويج -حيازة حبوب محظورة -سجائر حشيش -إقرار -ثبوت إدانة -حد املسكر -تعزير باجللد والسجن والغرامة واملصادرة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33475549 :‬تاريخه ‪1433/12/22 :‬هـ‬\n                     ‫رقم القضية ‪33204824 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‬\n            ‫‪ 3421501:‬تاريخه ‪1434/1/25:‬هـ‬\n\n\n  ‫مســكر ‪ -‬مخــدرات ‪ -‬حيــازة مســكر ‪ -‬حيــازة حشــيش بقصــد التعاطــي‬\n  ‫والترويــج ‪ -‬حيــازة حبــوب محظــورة ‪ -‬ســجائر حشــيش ‪ -‬إقــرار ‪ -‬ثبــوت‬\n  ‫إدانــة ‪ -‬حــد املســكر ‪ -‬تعزيــر باجللــد والســجن والغرامــة واملصــادرة‬\n                                                      ‫واملنــع مــن الســفر‪.‬‬\n\n\n\n\n                                               ‫‪ -1‬قاعدة ‪ :‬ال عذر ملن أقر‪.‬‬\n                                         ‫‪ -2‬قاعدة املرء مؤاخذ بإقراره ‪.‬‬\n                        ‫‪ -3‬من مقاصد الشريعة حفظ النفس والعقل ‪.‬‬\n                          ‫‪ -4‬الفقرة الثالثة من نظام مكافحة املخدرات ‪.‬‬\n  ‫‪ -5‬املــواد (‪ )38‬و (‪ )41‬و (‪ )53‬و (‪ )56‬و (‪ )59‬و (‪.)62‬مــن نظــام مكافحــة‬\n                                                               ‫املخــدرات ‪.‬‬\n\n\n\n  ‫توجيــه االتهــام للمدعــى عليهمــا األول ‪ :‬بحيــازة قطعــة حشــيش بقصــد‬\n  ‫البيــع والشــروع يف بيعهــا بقصــد االجتــار والترويــج‪ ،‬تســليمه للثانــي‬\n  ‫لقطعــة حشــيش بقصــد الترويــج واالجتــار‪ ،‬حيــازة قطــع مــن احلشــيش‬\n  ‫وحبــوب الكلونازيبــام احملظــورة بقصــد التعاطــي والترويــج‪ ،‬تعاطيــه‬\n  ‫للحشــيش املخــدر‪ ،‬والثانــي ‪ :‬حيــازة قطــع مــن احلشــيش املخــدر وســجائر‬\n\n                                                                                 ‫‪246‬‬\n\f      ‫حشــيش بقصــد التعاطــي والترويــج‪ ،‬تعاطــي احلشــيش املخــدر‪ ،‬شــرب‬\n      ‫املســكر‪ ،‬حيازة قارورة مســكر‪ ،‬حيث ورد بالغ ملكافحة املخدرات‬\n      ‫مــن أحــد املصــادر عــن قيــام املدعــى عليــه األول بترويــج احلشــيش علــى‬\n      ‫نطــاق واســع‪ ،‬أبــدى املصــدر اســتعداده لإلطاحــة بــه عــن طريــق أحــد‬\n      ‫الوســطاء الذيــن يحضــرون احلشــيش منــه وهــو املدعــى عليــه الثانــي‪،‬‬\n      ‫اتصل املصدر على املدعى عليه الثاني وطلب منه كمية من احلشيش‪،‬‬\n      ‫فقــام املدعــى عليــه الثانــي باالتصــال علــى املدعــى عليــه األول ثــم اتصل‬\n      ‫بالوســيط وأخبــره أن املــروج (املدعــى عليــه األول) أفــاد بوجــود نوعــن‬\n      ‫مــن احلشــيش‪ ،‬ومت التفــاوض علــى الســعر وانتهــت املكاملــة وكانــت‬\n      ‫علــى مســمع مــن رجــال األمــن‪ ،‬مت التوجــه ملنــزل املدعــى عليــه الثانــي‬\n      ‫برفقــه املصــدر (مــكان التســليم)‪ ،‬متــت مداهمــة البيــت والقبــض عليــه‬\n      ‫وعثــر معــه علــى احلشــيش املخــدر بيــده‪ ،‬كمــا عثــر يف جيبــه علــى عــدد‬\n      ‫مــن حبــوب الــروش‪ ،‬بتفتيــش ســيارته عثــر علــى أربــع قطــع حشــيش‪،‬‬\n      ‫بســؤاله عــن مصــدر احلشــيش أفــاد أنــه يأخذهــا مــن املدعــى عليــه‬\n      ‫األول وأنــه مجــرد وســيط‪ ،‬مت القبــض علــى املدعــى عليــه األول داخــل‬\n      ‫منــزل أحــد أصدقائــه وعثــر معــه علــى قطعــة حشــيش‪ ،‬اعتــرف املدعــى‬\n      ‫عليــه األول بــأن املضبــوط معــه يعــود لــه وليــس ملــن يف املجلــس معــه أي‬\n      ‫عالقــة‪ ،‬بتفتيــش ســيارة املدعــى عليــه األول عثــر علــى قطعــه حشــيش‪،‬‬\n      ‫باالنتقــال ملنــزل األول عثــر علــى قطعــه حشــيش وقــارورة خمــر‪ ،‬طلــب‬\n      ‫املدعــي العــام أثبــات مــا أســند للمدعــى عليهمــا‪ ،‬احلكــم عليهمــا بعقوبه‬\n      ‫الســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة هاتفــي اجلــوال‬\n      ‫العائديــن لــأول والثانــي‪ ،‬وإســقاط شــريحتهما‪ ،‬إجــراء املقتضــى‬\n      ‫الشــرعي بحــق الثانــي لقــاء تعاطيــه احلشــيش‪ ،‬احلكــم علــى األول بحــد‬\n\n\n‫‪247‬‬\n\f‫املســكر لقــاء إقــراره بشــربه وتعاطيــه احلشــيش‪ ،‬احلكــم علــى األول‬\n‫بعقوبــة تعزيــره لقــاء حيــازة املســكر بقصــد الشــرب‪ ،‬أقــر املدعــي عليه‬\n‫األول مبــا نســب إليــه‪ ،‬أقــر املدعــي عليــه الثانــي مبــا نســب إليــه وذكــر‬\n‫بــأن قصــده مــن احليــازة التعاطــي‪ ،‬صــدر احلكــم بإثبــات اإلدانــة وإقامــة‬\n‫حــد املســكر عليهمــا‪ ،‬والتعزيــر بالســجن واجللــد واملنــع مــن الســفر‬\n        ‫والغرامــة واملصــادرة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األحــد ‪1433/8/4‬ه ـ الســاعة التاســعة والنصــف افتتحــت‬\n‫اجللســة لــدي أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى‬\n‫املعاملــة احملالــة لــي مــن فضيلــة رئيــس احملكمــة برقــم وتاريــخ‬\n‫‪1433/3/22‬ه ـ واملقيــدة بــوارد احملكمــة برقــم يف ‪1433/3/22‬ه ـ‬\n‫وفيــه حضــر املدعــي العــام ‪ ...‬وحضــر حلضــوره املدعــى عليــه األول ‪...‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر املدعــى عليــه‬\n‫الثانــي ‪ ..‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــى األول‬\n‫قائــا يف حتريــر دعــواه أنــه بتاريــخ ‪1433/2/14‬ه ـ ورد بــاغ مــن أحــد‬\n‫املصــادر الســرية لشــعبة مكافحــة املخــدرات بالدمــام مفــاده وجــود‬\n‫شــخص يدعــى (‪ )...‬يقــوم بترويــج احلشــيش املخــدر علــى نطــاق واســع‬\n‫وأبــدى املصــدر اســتعداده لإلطاحــة باملتهــم عــن طريــق أحــد الوســطاء‬\n‫الذيــن يحضــرون احلشــيش منــه ويدعــى ‪ ..‬ويســتخدم اجلــوال رقــم (‪)...‬‬\n‫ـاء عليــه مت االتصــال علــى املدعــو ‪ ..‬وبعــد الســام طلــب املصــدر منــه‬\n                                                                          ‫وبنـ ً‬\n                                                                                     ‫‪248‬‬\n\f      ‫نصــف ربــع مــن احلشــيش املخــدر فقــال الوســيط حلظــات اتصــل علــى ‪...‬‬\n      ‫وأرد لــك خبــر انتهــت املكاملــة وبعــد حوالــي خمــس دقائــق اتصــل‬\n      ‫الوســيط املدعــو ‪ ..‬علــى املصــدر وأخبــره أن املدعــو ‪ ..‬أفــاد بوجــود نوعــن‬\n      ‫مــن احلشــيش املخــدر وهــي (زنقــة) و (دار) وهــي أســماء تطلــب علــى‬\n      ‫أنــواع مــن احلشــيش فأخبــره املصــدر بأنــه يريــد نــوع (زنقــه) وســأله بكم‬\n      ‫يحســب لــي نصــف الربــع فأجــاب املدعــو ‪ ...‬بــأن قيمتهــا ألــف وتســع مئــة‬\n      ‫ريــال فقــال لــه املصــدر إن املبلــغ كبيــر علــى نصــف الربــع وطلــب‬\n      ‫تخفيــض املبلــغ فوافــق املدعــو ‪ ...‬علــى أن يصبــح املبلــغ (‪ )1850‬ألف ـ ًا‬\n      ‫وثمــان مئــة وخمســن ريــا ًال وأفــاد املتهــم ‪ ..‬أنــه ســوف يأخذهــا مــن ‪...‬‬\n      ‫وانتهــت املكاملــة وكانــت املكاملــات مســموعة مــن قبــل رجــال األمــن‬\n      ‫فتــم تفتيــش املصــدر واالنتقــال ملنزلــه وعنــد الوصــول ملنــزل املصــدر‬\n      ‫اتصــل املصــدر علــى املتهــم ‪ ..‬وقــال لــه وينــك فأجــاب أنــه ينتظــر املدعــو‬\n      ‫‪ ...‬وإذا جــاء ســوف يقــوم باالتصــال عليــه وأخبــر املصــدر املتهــم ‪ ..‬بأنــه يف‬\n      ‫املنــزل يف انتظــاره وانتهــت املكاملــة وكانــت مســموعة مــن قبــل أحــد‬\n      ‫رجــال األمــن بالفرقــة القابضــة وبعــد حوالــي ســاعة اتصــل املصــدر علــى‬\n      ‫املتهــم ‪ ..‬وســأله عــن مــكان تواجــده فأفــاد املتهــم أنــه موجود وســيحضر‬\n      ‫بعــد نصــف ســاعة وأخبــر املصــدر املتهــم ‪ ..‬أنــه لوحــده يف البيــت وطلــب‬\n      ‫منــه الدخــول مباشــرة وانتهــت املكاملــة وكانــت مســموعة مــن قبــل‬\n      ‫رجــل األمــن وعنــد وصــول املتهــم قــام بدخــول املنــزل ومت مداهمتــه‬\n      ‫والقبــض عليــه والعثــور معــه علــى احلشــيش املخــدر بيــده اليمنــى بلــغ‬\n      ‫وزنــه (‪ )77.3‬ســبعة وســبعني جرامـ ًا وثالثــة أعشــار اجلــرام كمــا عثــر يف‬\n      ‫جيبــه األميــن علــى كيــس بــه عــدد خمــس حبــات يشــتبه أن تكــون مــن‬\n      ‫حبــوب الــروش املنبهــة وبتفتيــش ســيارته عثــر علــى أربــع قطــع حشــيش‬\n\n\n‫‪249‬‬\n\f‫بلــغ وزنهــا (‪ )91.4‬واحــد ًا وتســعني جرامــا وأربعة أعشــار اجلرام وبســؤاله‬\n‫عــن مصــدر احلشــيش أفــاد أنــه يأخذهــا مــن املدعــو ‪ ...‬وأنــه مجــرد‬\n‫وســيط مبقابــل مئــة ريــال ومت متكينــه مــن االتصــال علــى املدعــو ‪...‬‬\n‫وأخبــره أن املبلــغ معــه فــرد املدعــو ‪ ...‬بقولــه ‪ :‬شــوي وأمــرك وانتهــت‬\n‫املكاملــة وبعــد حوالــي عشــر دقائــق اتصــل ‪..‬علــى املدعــو ‪ ...‬واخبــره‬\n‫مبكانــه وأنــه ســيتجه إلــى منــزل ‪ ...‬وطلــب مــن ‪ ..‬احلضــور لــه هنــاك‬\n‫وكانــت جميــع املكاملــات حتــت مســامع رجــال األمــن فتــم التوجــه ملنزل‬\n‫‪ ...‬حيــث شــوهدت ســيارة املتهــم ‪ ...‬املعروفــة مســبق ًا للفرقــة القابضــة ومت‬\n‫االتصــال ‪ ...‬وطلــب نــزول املتهــم لــه إال أنــه خوفـ ًا مــن هــروب املتهــم ‪ ..‬متــت‬\n‫مداهمــة املجلــس حيــث عثــر علــى ثالثــة أشــخاص األول املتهــم ‪...‬‬\n‫وبتفتيشــه عثــر معــه علــى أربــع ســجائر ملفوفــة لــف يــدوي ممزوجــة‬\n‫باحلشــيش املخــدر بلــغ وزنهــا (‪ )6‬ســتة جرامــات كمــا عثــر معــه علــى‬\n‫قطعــة حشــيش بلــغ وزنهــا (‪ )4.3‬أربعــة جرامــات وثالثــة أعشــار اجلــرام‬\n‫وقطعــة أخــرى بلــغ وزنهــا (‪ )6.5‬ســتة جرامــات وخمســة أعشــار اجلــرام‬\n‫وبتفتيــش الشــخصني املرافقــن لــه يف املجلــس وهــم‪ ...‬و‪...‬لــم يعثــر معهــم‬\n‫علــى أي ممنوعــات واعتــرف املتهــم ‪ ...‬بــأن املضبــوط معــه يعــود لــه وليــس‬\n‫لهمــا أي عالقــة أو علــم بهــا ومت أخــذ إقــرار عليــه بذلــك (ومت إخــاء‬\n‫ســبيل كل مــن ‪ ..‬و‪...‬مــن قبــل املكافحــة لعــدم عالقتهــم مبــا جــرى)‬\n‫وبتفتيــش ســيارة املتهــم ‪ ...‬عثــر علــى قطعــة حشــيش بلــغ وزنهــا (‪)499‬‬\n‫أربــع مئــة وتســعة وتســعني جرام ـ ًا عليهــا ختــم (دارد دار) ‪-‬وهــو أحــد‬\n‫النوعــن اللذيــن قــام املتهــم ‪ ...‬بعرضهمــا علــى املصــدر ‪-‬وباالنتقــال ملنــزل‬\n‫املتهــم ‪ ...‬عثــر علــى قطعــة حشــيش بلــغ وزنهــا (‪ )36‬ســتة وثالثــن جرامـ ًا‬\n‫وقــارورة بهــا القليــل مــن ســائل يشــتبه أن يكــون مــن اخلمــر فتــم القبــض‬\n\n\n                                                                                            ‫‪250‬‬\n\f      ‫عليــه وقــد أبــدى املدعــى عليهمــا تعاونهمــا مــع مكافحــة املخــدرات‬\n      ‫لإلطاحــة ببعــض مروجــي املخــدرات وقــد ورد التقريــر الكيمــاوي‬\n      ‫الشــرعي رقم‪716‬وتاريخ‪1433/2/23‬ه ـ املتضمــن ثبــوت إيجابيــة‬\n      ‫العينــات املضبوطــة مــن احلبــوب لعقــار الكلونازيبــام واملعــروف جتاري ـ ًا‬\n      ‫باســم ريفوتــرل واملدرجــة يف اجلــدول الثانــي فئــة (د) واملرفــق بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر ذاتــه‬\n      ‫إيجابيــة عينــات الكميــات املضبوطــة مــن القطــع والســجائر املشــار‬\n      ‫إليهــا أعــاه ملــادة احلشــيش املخــدرة واحملظــورة واملدرجــة يف اجلــدول‬\n      ‫األول فئــة (أ) واملرفــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫كمــا أثبــت إيجابيــة عينــة القــارورة املضبوطــة ملــادة الكحــول اإليثيلــي‬\n      ‫وبنســبه مســكره وبســماع أقــوال املتهــم ‪ ...‬عنــاب األوليــة أقــر بحيازتــه‬\n      ‫ملــا ضبــط معــه وتعاطيــه للحشــيش املخــدر وأنكــر مــا ســوى ذلــك‬\n      ‫وبســماع أقــوال املتهــم ‪ .. ..‬أقــر بحيازتــه ملــا ضبــط معــه مــن حشــيش ومــا‬\n      ‫ضبــط أيضــا مبنزلــه وســيارته وأقــر بتعاطيــه احلشــيش وشــرب املســكر‬\n      ‫وباســتجواب املتهــم ‪ ...‬عنــاب أقــر بإحضــاره احلشــيش املخــدر للمصــدر‬\n      ‫إال أنــه لــم يقصــد الترويــج وإمنــا قــام بشــراء الكميــة مناصفــة بينــه وبــن‬\n      ‫املصــدر كمــا أقــر بحيازتــه للحشــيش املضبــوط بســيارته وأنــه لــه‬\n      ‫بقصــد االســتعمال الشــخصي وأنــه يتعاطــى احلشــيش املخــدر وأقــر‬\n      ‫بحيازتــه حلبــوب الــروش املضبوطــة معــه بقصــد االســتعمال وباســتجواب‬\n      ‫املتهــم ‪ ..‬أقــر بحيازتــه للحشــيش املضبــوط معــه واملضبــوط بســيارته‬\n      ‫واملضبــوط مبنزلــه وحيازتــه لقــارورة املســكر أيضـ ًا كل ذلــك بقصــد‬\n      ‫االســتعمال وأنــه يتعاطــى احلشــيش املخــدر ويشــرب املســكر وأنكــر‬\n      ‫مــا ســوى ذلــك وقــد انتهــى التحقيــق إلــى اتهامهمــا مبــا يلــي ‪:‬ـ‪ -1‬حيــازة‬\n\n\n‫‪251‬‬\n\f‫املتهــم ‪ ..‬قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )77.3‬ســبعة وســبعني‬\n‫جرام ـ ًا وثالثــة أعشــار اجلــرام بقصــد البيــع والشــروع يف بيعهــا بقصــد‬\n‫االجتــار والترويــج‪ -2.‬تســليم املتهــم ‪ ...‬قطعــة مــن احلشــيش املخــدر بلــغ‬\n‫وزنهــا (‪ )77.3‬ســبعة وســبعني جرام ـ ًا وثالثــة أعشــار اجلــرام بقصــد‬\n‫الترويــج واالجتــار ‪-3.‬حيــازة املتهــم ‪ ...‬ألربــع قطــع مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )91.4‬واحــد ًا وتســعني جرامــا وأربعــة أعشــار اجلــرام ولــ(‪)5‬‬\n‫خمــس حبــات مــن حبــوب الكلونازيبــام احملظــورة بقصــد التعاطــي‬\n‫والترويــج وتعاطيــه احلشــيش املخــدر ‪ -4.‬حيــازة املتهــم ‪ ...‬لقطــع مختلفــة‬\n‫األحجــام مــن احلشــيش املخــدر بلــغ وزن مجموعهــا (‪ )545.8‬خمــس مئــة‬\n‫وخمســة وأربعــن جرامـ ًا وثمانيــة أعشــار اجلــرام وألربــع ســجائر مخلوطة‬\n‫باحلشــيش بلــغ وزنهــا (‪ )6‬ســتة جرامــات بقصــد التعاطــي و الترويــج‬\n‫وتعاطيــه احلشــيش املخــدر ‪ -5.‬شــرب املتهــم ‪ ...‬املســكر وحيازتــه‬\n‫لقــارورة بهــا القليــل مــن املســكر بقصــد الشــرب وذلــك لألدلــة والقرائن‬\n‫التاليــة ‪ -1 :‬إقــرار املتهــم ‪ ..‬حتقيق ـ ًا املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقم‪1.2‬واملرفــق لفــة رقــم‪ 21.22‬واملــدون علــى الصفحــة رقم‪18‬واملرفــق‬\n‫لفــة رقــم ‪ -2 .1‬إقــرار املتهــم ‪ ...‬حتقيقـ ًا املنــوه عنــه واملــدون على الصفحة‬\n‫رقم‪1.2‬واملرفــق لفــة رقــم‪ 24.25‬واملــدون علــى الصفحــة رقم‪19‬واملرفــق‬\n‫لفــة رقــم ‪ 1‬وكذلــك املرفــق لفــه رقــم‪ -3.3‬مــا ورد يف محضــر البــاغ‬\n‫املنــوه عنــه مبحضــر االســتدالل واملــدون علــى الصفحــة رقم‪2‬واملرفــق لفة‬\n‫رقــم‪ -4 .1‬مــا ورد يف محضــر القبــض مــن وقائــع املنــوه عنهــا واملدونــة‬\n‫علــى الصفحــة رقم‪11.12.13.14‬واملرفقــة لفــة رقــم‪ -5 .1‬مــا ورد يف‬\n‫التقريــر الكيمــاوي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم ‪40، 39‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــوران ‪ -‬وهمــا بكامــل أهليتهمــا املعتبرة‬\n\n\n                                                                                        ‫‪252‬‬\n\f      ‫شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا‬\n      ‫أســند إليهمــا وفق ـ ًا للفقــرة رقــم (‪ )2,7‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n      ‫مكافحـ ــة املخ ـ ــدرات واملــؤثـ ــرات العقليــة واحلكــم عليهمــا مبــا يلــي‪:‬‬\n      ‫‪ -1‬عقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫رقــم (‪ )38‬مــن النظــام‪ ،‬مــع مراعــاة مقتضــى املــادة (‪ )62‬مــن ذات النظام‬\n      ‫بحقهمــا واملــادة (‪ )59‬بحــق ‪ -2. ..‬منعهمــا مــن الســفر إعمــاال ملقتضــى‬\n      ‫الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن النظــام ‪3.‬ـ مصــادرة الهاتــف‬\n      ‫اجلــوال العائــد للمدعــو ‪ ...‬الــذي يحمــل الرقــم املصنعــي ( ‪ )........‬ورقمــه‬\n      ‫(‪ )...‬وكذلــك الهاتــف اجلــوال العائــد للمتهــم ‪ ...‬الــذي يحمــل الرقــم‬\n      ‫املصنعــي(‪ )........‬ورقمــه (‪ )...‬الســتخدامهما يف الترويــج وفق ـ ًا للفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام‪ ،‬مــع املطالبة بإســقاط شــريحة‬\n      ‫الهاتــف النقــال وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو وزيــر‬\n      ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬هــ‪4.‬ـ املقتضــى الشــرعي‬\n      ‫بحــق ‪ ..‬لقــاء تعاطيــه احلشــيش املخــدر ‪5.‬ـ احلكــم علــى املتهــم ‪...........‬‬\n      ‫بحــد الســكر لقــاء إقــراره بشــرب املســكر وتعاطيــه احلشــيش املخــدر‪.‬‬\n      ‫‪6‬ـ احلكــم علــى املتهــم ‪ ......... .‬بعقوبــة تعزيريــة تزجــره وتــردع غيــره لقــاء‬\n      ‫حيازتــه املســكر بقصــد الشــرب هــذه دعــواي وبعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليهمــا أجــاب املدعى عليــه األول ‪ ...‬قائال ‪ :‬ماذكره‬\n      ‫املدعــي العــام مــن حيازتــي لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫(‪ )3,77‬ســبعة وســبعني جرامــا وثالثــة أعشــار اجلــرام بقصــد البيــع مــن‬\n      ‫الشــروع يف بيعهــا بقصــد االجتــار والترويــج وحيازتــي ألربــع قطــع مــن‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا(‪ )91,4‬واحــدا وتســعني جرامــا وأربعــة‬\n      ‫أعشــار اجلــرام وخمــس حبــات مــن حبــوب الكلونازيبــام احملظــورة‬\n\n\n‫‪253‬‬\n\f‫بقصــد التعاطــي والترويــج وتعاطــي للحشــيش املخــدر فكلــه صحيــح‬\n‫جملــة وتفصيــا علمــا أنــه ال ســوابق علــي وأنــا تائــب إلــى اهلل ونــادم علــى‬\n‫هــذا الفعــل هــذه إجابتــي وأجــاب املدعــى عليــه الثانــي ‪ ...‬قائــا ما ذكره‬\n‫املدعــي العــام يف دعــواه مــن قيامــي بتســليم قطعــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )77,3‬ســبعة وســبعني جرامــا وثالثــة أعشــار اجلــرام بقصــد‬\n‫االجتــار والترويــج فغيــر صحيــح وأمــا ماذكــره املدعــي العــام يف دعــواه‬\n‫مــن حيازتــي لقطــع مختلفــة األحجــام مــن احلشــيش املخــدر بلــغ‬\n‫وزنهــا(‪ )545،8‬خمســمائة وخمســة وأربعــن جرامــا وثمانيــة أعشــار‬\n‫اجلــرام وألربــع ســجائر مخلوطــة باحلشــيش بلــغ وزنهــا (‪ )6‬ســتة جرامــات‬\n‫بقصــد الترويــج فغيــر صحيــح وإمنــا الصحيــح أنني قمت بحيــازة الكمية‬\n‫املذكــورة بقصــد التعاطــي وقيامــي بتعاطيــه احلشــيش املخــدر وأمــا مــا‬\n‫ذكــره املدعــي العــام يف دعــواه مــن قيامــي بشــرب املســكر وحيازتــي‬\n‫لقــارورة بهــا القليــل مــن املســكر بقصــد الشــرب فصحيــح والســابقة‬\n‫صحيحــة هــذه إجابتــي وبســؤال املدعــي العــام عــن البينــة التــي ثبــت‬\n‫صحــة دعــواه مــن قيــام املدعــى عليــه الثانــي بتســليم قطعــة مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا (‪ )77,3‬ســبعة وســبعني جرامــا وثالثــة أعشــار اجلــرام‬\n‫بقصــد االجتــار والترويــج أجــاب قائــا ليس لدي إال مــا يف أوراق املعاملة‬\n‫وعليــه رفعــت اجللســة لالطــاع علــى أوراق املعاملــة وتأجلــت يف تاريــخ‬\n‫‪1433/8/25‬ه ـ يــوم األحــد الســاعة احلاديــة عشــر وبــاهلل التوفيــق وصلى‬\n‫اهلل علــى ســيدنا محمــد وعلــى آله وصحبه وســلم حــرر يف ‪1433/8/4‬هـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1433/9/10‬ه ـ الســاعة‬\n‫احلاديــة عشــرة افتتحــت اجللســة وفيهــا حضــر األطــراف وباالطــاع علــى‬\n‫أوراق املعاملــة وجــدت بــن طياتهــا علــى اللفــة رقــم (‪ )1‬ص ‪14-11‬‬\n\n\n                                                                                       ‫‪254‬‬\n\f      ‫محضــر القبــض والتفتيــش والــذي جــاء فيــه أن املدعــى عليــه األول ‪...‬‬\n      ‫قــام باالتصــال علــى املدعــى عليــه الثانــي ‪ ...‬علــى مســمع مــن الفرقــة‬\n      ‫القابضــة وأن ‪ ...‬رد بقولــه شــوي وأمــرك ثــم اتصــل عليــه ‪ ...‬وأخبــر‬\n      ‫مبكانــه وأنــه ســيتجه إلــى منــزل أبــي‪ ...‬وطلــب مــن ‪ ...‬احلضــور هنــاك‬\n      ‫وكانــت جميــع املكاملــات حتــت مســمع مــن الفرقــة القابضــة وبعرضــه‬\n      ‫علــى املدعــى عليــه الثانــي أجــاب قائــا مــا ذكــر غيــر صحيــح هــذا وقــد‬\n      ‫جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي رقــم ‪ 716‬وتاريــخ‬\n      ‫‪1433/2/23‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة‬\n      ‫إقــرار املدعــى عليــه األول ‪ ...........‬ملــا نســب إليــه يف دعــوى املدعــي العــام‬\n      ‫ومبــا أنــه ال عــذر ملــن أقــر ومبــا أن املــرء مؤاخــذ بإقــراره ومبــا أن املدعــى‬\n      ‫عليــه الثانــي ‪ ...‬قــد أقــر بتعاطيــه للحشــيش املخــدر وشــرب املســكر‬\n      ‫وحيازتــه لقــارورة بهــا القليــل مــن املســكر بقصــد الشــرب ومبــا أنــه‬\n      ‫أنكــر قيامــه بتســليم قطعــة احلشــيش املذكــورة يف الدعــوى للمدعــى‬\n      ‫عليــه األول بقصــد االجتــار وإنــكاره حليــازة قطــع مختلفــة مــن احلشــيش‬\n      ‫املخــدر وأربــع ســجائر بقصــد الترويــج وإمنــا كان قصــده مــن ذلــك‬\n      ‫التعاطــي ومبــا أن املدعــي العــام اكتفــى مبــا يف أوراق املعاملــة وبنــاء‬\n      ‫علــى مــا جــاء يف محضــر القبــض والتفتيــش املنــوه عنــه بعاليــه ومبــا أن‬\n      ‫املدعــى عليــه الثانــي أقــر بصحــة الســابقة وبنــاء علــى مايلــي ‪1 :‬ـ حيــازة‬\n      ‫املدعــى عليــه األول ‪ ..‬للحشــيش احملظــور بقصــد الترويــج فعــل محــرم‬\n      ‫شــرع ًا ملــا حتتويــه هــذه املخــدرات مــن مــواد أثبــت الطــب ضررهــا علــى‬\n      ‫العقــل والبــدن والشــريعة اإلســامية جــاءت بحفظهمــا وملــا يترتــب علــى‬\n      ‫ترويجهــا و اســتخدامها مــن نتائــج ســيئة علــى الفــرد واملجتمــع وهــو‬\n      ‫كذلــك مجــرم نظام ـ ًا ملــا نصــت عليــه الفقــرة الثانيــة مــن املــادة الثالثــة‬\n\n\n‫‪255‬‬\n\f‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ ومعاقــب عليــه بالعقوبــة‬\n‫األصليــة الــواردة يف املــادة الثامنــة والثالثــن والعقوبــة التكميليــة‬\n‫الــواردة يف املــادة السادســة واخلمســن مــن النظــام املشــار إليــه ‪2‬ـ تعاطــي‬\n‫املدعــى عليهمــا للحشــيش املخــدر واخلمــر املســكر وهمــا مكلفــان‬\n‫مختــاران فعــل محــرم شــرع ًا ومعاقــب عليــه باحلد الشــرعي ‪3‬ـ ماتضمنه‬\n‫التقريــر الكيميائــي املشــار إليــه ‪4‬ـ اســتخدام املدعــى عليــه األول ‪...‬‬\n‫ل ــلهاتف النقــال يف عمليــة الترويــج يســتوجب مصادرتــه وفقـ ًا ملــا نصــت‬\n‫عليــه املــادة الثالثــة واخلمســن مــن النظــام املذكــور ووفق ـ ًا لتعميــم‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة ‪ -5‬اســتناد ًا ملــا جــاء يف املــادة‬\n‫التاســعة واخلمســن والثانيــة والســتني مــن نظــام مكافحــة املخــدرات‬\n‫‪-6‬حيــازة املدعــى عليــه الثانــي ‪ ...‬للحشــيش املخــدر بقصــد التعاطــي‬\n‫فعــل محــرم شــرعا ملــا حتتويــه هــذه املخــدرات مــن مــواد أثبــت الطــب‬\n‫ضررهــا علــى العقــل والبــدن وملــا يترتــب علــى تعاطيهــا مــن نتائــج ســيئة‬\n‫علــى الفــرد واملجتمــع ومجــرم نظامــا ملــا نصــت عليــه الفقــرة الثانــي مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ ومعاقــب عليــه بالعقوبــة‬\n‫األصليــة الــواردة يف املــادة احلاديــة واألربعــن والعقوبــة التكميليــة‬\n‫الــواردة يف املــادة السادســة واخلمســن مــن النظــام املشــار إليــه ‪ -‬إقــرار‬\n‫املدعــى عليــه حليــازة قــارورة بهــا القليــل مــن املســكر بقصــد الشــرب‬\n‫فعــل محــرم شــرعا ومعاقــب عليــه بعقوبــة تعزيــره لــذا كلــه فقــد قــررت‬\n‫مايلــي ‪ :‬أوال ثبــت لــدي إدانــة املدعــى عليــه األول ‪ ...‬بحيــازة قطعــة‬\n‫حشــيش بلــغ وزنهــا (‪)77.3‬ســبعة وســبعني جرامــا وثالثــة أعشــار اجلــرام‬\n\n\n                                                                                     ‫‪256‬‬\n\f      ‫بقصــد البيــع والشــروع يف بيعهــا بقصــد االجتــار والترويــج وحيازتــه‬\n      ‫ألربــع قطــع مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )91.4‬واحــدا وتســعني‬\n      ‫وأربعــة أعشــار اجلــرام وخمــس حبات من حبــوب الكلونازيبام احملظورة‬\n      ‫بقصــد التعاطــي والترويــج وقــررت تعزيــره علــى ذلــك بســجنه ملــدة خمس‬\n      ‫ســنوات حتتســب منهــا مــدة توقيفــه الســابقة علــى ذمــة هــذه القضيــة‬\n      ‫ومنعــه مــن الســفر إلــى خــارج هــذه البــاد مــدة مماثلــة لســجنه وجلــده‬\n      ‫مائتــن وخمســن جلــدة مفرقــة علــى خمــس دفعــات كل دفعــة خمســون‬\n      ‫جلــدة بــن كل دفعــة واألخــرى مــدة التقــل عــن عشــر أيــام وتغرميــه مبلغــا‬\n      ‫وقــدره خمســة اآلف ريــال تــودع يف خزينــة الدولــة ثانيــا ثبــت لــدي تعاطي‬\n      ‫املدعــى عليــه األول ‪ ...‬للحشــيش املخــدر وقــررت إقامــة املســكر عليــه‬\n      ‫وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا ثالثــا ثبــت لــدي اســتخدام‬\n      ‫املدعــى عليــه األول للهاتــف اجلــوال ذي الرقــم املصنعــي(‪ )........‬وقــررت‬\n      ‫مصادرتــه وعــدم صــرف شــريحة االتصــال ذات الرقــم (‪ )...‬لنفــس‬\n      ‫املســتخدم رابعــا ثبــت لــدي إدانــة املدعــى عليه الثاني ‪ ..‬بتعاطي احلشــيش‬\n      ‫املخــدر وبشــرب املســكر وقــررت إقامــة حــد املســكر عليــه وذلــك‬\n      ‫بجلــده ثمانــن جلــدة دفعــة واحــده علنــا خامســا ثبــت لــدي حيــازة املدعــى‬\n      ‫عليــه الثانــي ‪ ...‬لقــارورة بهــا القليــل مــن املســكر بقصــد الشــرب وقــررت‬\n      ‫تعزيــره علــى ذلــك بجلــده أربعــن جلــدة دفعــة واحــدة سادســا لــم يثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه الثانــي ‪ ...‬بتســليمه قطعــة مــن احلشــيش املخــدر‬\n      ‫بلــغ وزنهــا (‪ )77.3‬ســبعة وســبعني جرامــا وثالثــة أعشــار اجلــرام بقصــد‬\n      ‫الترويــج واالجتــار وقــررت صــرف النظــر عــن مطالبــة املدعــي العــام‬\n      ‫تطبيــق الفقــرة األولــى مــن املــادة الثامنــة والثالثــن مــن نظــام مكافحــة‬\n      ‫املخــدرات والفقــرة األولــى والثالثــة واخلمســن مــن النظــام ذاتــه لعــدم‬\n\n\n‫‪257‬‬\n\f‫ثبــوت موجبهــا ‪ -7‬ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪ ...‬بحيازتــه‬\n‫لقطــع مختلــف األحجــام مــن احلشــيش املخــدر بلــغ وزنهــا (‪)545.8‬‬\n‫خمســمائة وخمســة وأربعــن جرامــا وثمانيــة أعشــار اجلــرام وألربــع‬\n‫ســجائر مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )6‬ســتة جرامــات بقصــد‬\n‫التعاطــي وقــررت تعزيــره علــى ذلــك بســجنه مــدة ســنتني حتتســب منهــا‬\n‫مــدة توقيفــه الســابقة علــى ذمــة هــذه القضيــة ومنعــه مــن الســفر خــارج‬\n‫هــذه البــاد مــدة مماثلــة لســجنه وجلــده مائتــي جلــدة مفرقــة علــى أربــع‬\n‫دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى مــدة ال تقــل‬\n‫عــن عشــرة أيــام ثامنــا‪ :‬يكــون بــن كل جلــدة واألخــرى يف جميــع مــا‬\n‫تقــدم مــدة ال تقــل عــن عشــرة أيــام ومبــا تقــدم حكمــت وبعــرض احلكــم‬\n‫علــى املدعــى عليهمــا قــررا قناعتهمــا باحلكــم وقــرر املدعــي العــام‬\n‫اعتراضــه علــى احلكــم وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n‫اعتراضيــة فأجبتــه لطلبــه وقــررت رفــع احلكــم حملكمــة االســتئناف‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                         ‫حرر يف ‪1433/9/10‬هـ الساعة العاشرة والنصف‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/130458‬ج‪ 2‬وتاريــخ ‪1434/1/17‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n‫وتاريــخ ‪1434/1/7‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ .../‬املســجل برقــم وتاريــخ ‪1433/12/22‬ه ـ اخلــاص‬\n‫ـد‪/‬كل مــن ‪ ../1‬و‪ .../2‬يف قضيــة مخــدرات‬      ‫ٍ‬       ‫بدعوى‪/‬املدعــي العــام ضـ‬\n‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n\n\n                                                                                         ‫‪258‬‬\n\f      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n                                                         ‫حــرر يف ‪1434/1/24‬هــ‪.‬‬\n\n\n\n\n‫‪259‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":246,"source_page_end":259,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b9aad422f7300e39092a514209221a1e55f4c527c97fe11efde17c1474150283","normalized_text_hash":"38e7c3aceddf4bc896bd0062581a9421b8ec3a14727507b73bf070601bd2477a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p246-33475549"},{"id":"e500837c-e1d4-51ee-89e8-880821488fd8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطعة من احلشيش املخدر بقصد االجتار والتعاطي -الشروع يف الترويج -تعاطي احلشيش -درء حد شرب املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر -عدم التقيد بالوصف الوارد يف الئحة الدعوى وإعطاء المحكمة الفعل الوصف الذي يستحق .","document_number":"33292678","case_number":"33230689","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/10","year":"1434","subject":"مخدرات -حيازة قطعة من احلشيش املخدر بقصد االجتار والتعاطي -الشروع يف الترويج -تعاطي احلشيش -درء حد شرب املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر -عدم التقيد بالوصف الوارد يف الئحة الدعوى وإعطاء المحكمة الفعل الوصف الذي يستحق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33292678 :‬تاريخه ‪1433/6/10:‬هـ‬\n                    ‫رقم القضية ‪33230689:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 349180‬تاريخه ‪1434/01/12:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة قطعــة مــن احلشــيش املخــدر بقصــد االجتــار‬\n‫والتعاطــي ‪ -‬الشــروع يف الترويــج ‪ -‬تعاطــي احلشــيش ‪ -‬درء حــد شــرب‬\n‫املســكر ‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‪ -‬عــدم‬\n‫التقيــد بالوصــف الــوارد يف الئحــة الدعــوى وإعطــاء احملكمــة الفعــل‬\n                                                  ‫الوصــف الــذي يســتحق ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬املادة (‪ )159‬من نظام اإلجراءات اجلزائية ‪.‬‬\n                            ‫‪ -2‬املادة (‪ )39‬من نظام مكافحة املخدرات‪.‬‬\n            ‫‪ -3‬الفقرة األول من املادة (‪ )56‬من نظام مكافحة املخدرات‪.‬‬\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه بحيــازة قطعــة حشــيش بقصــد االجتــار‬\n‫والتعاطي‪ ،‬شــروعه يف ترويج احلشــيش‪ ،‬تعاطي احلشــيش املخدر‪،‬حيث‬\n‫ورد بــاغ مــن أحــد املصــادر الســرية عــن وجــود شــخص يقــوم بترويــج‬\n‫احلشــيش املخــدر والتوســط يف ترويجــه ويســتخدم اجلــوال‪ ،‬مت متكــن‬\n‫املصــدر مــن االتصــال بــه وطلــب منــه قطعــة حشــيش مخــدر فــرد عليــه‬\n‫وأخبــره بوجــود شــخص آخــر يف نفــس مدينــة املتصــل ســوف يوفــر لــه‬\n‫احلشــيش فوافــق املصــدر وأعطــاه املــروج رقــم الوســيط‪ ،‬مت تفتيــش‬\n\n                                                                                 ‫‪260‬‬\n\f      ‫املصــدر وتســليمه املبلــغ احلكومــي املرقــم وتكليــف أحــد األفــراد‬\n      ‫مبرافقتــه‪ ،‬قــام الشــخص ( الوســيط املدعــى عليــه ) باالتصــال علــى‬\n      ‫املصــدر وتقابــا يف املــكان احملــدد‪ ،‬حضــر املدعــى عليــه بســيارة ال‬\n      ‫تعــود ملكيتهــا لــه‪ ،‬قــام رجــل األمــن بالركــوب معــه نيابــة عــن املصــدر‬\n      ‫والحــظ قطعــة حشــيش بيــده اليمنــى وأثنــاء اســتالمه قــام رجــل األمــن‬\n      ‫بالســيطرة عليــه بعــد محاولتــه الهــرب‪ ،‬عثــر بداخــل الســيارة علــى قطعة‬\n      ‫حشــيش‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم‬\n      ‫عليــه بعقوبــة الســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة‬\n      ‫اجلــوال واحلكــم عليــه باملقتضــى الشــرعي العترافــه بتعاطــي احلشــيش‪،‬‬\n      ‫أنكــر املدعــى عليــه مــا نســب إليــه‪ ،‬أحضــر املدعــي العــام شــاهدين‬\n      ‫مــن أعضــاء الفرقــة القابضــة‪ ،‬كمــا جــرى الرجــوع إلــى أقــوال املدعــى‬\n      ‫عليــه حتقيقـ ًا أنكــر املدعــى عليــه الشــهادة ورجــع عــن أقوالــه حتقيقـاً‪،‬‬\n      ‫صــدر احلكــم بــدرء حــد املســكر‪ ،‬وتعزيــره لقــاء توجــه التهمــة فيمــا‬\n      ‫نســب إليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‪ ،‬صــدق احلكــم‬\n                                                         ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ 0000‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 0000‬وتاريــخ ‪ 1433/04/03‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 0000‬وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم‬\n      ‫اإلثنــن املوافــق‪ 1433/06/02‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 36‬‬\n      ‫وفيهــا حضــر حضــر املدعــي العــام ‪ 0000‬وادعــى علــى احلاضــر معــه‬\n\n‫‪261‬‬\n\f‫‪ 0000‬مبوجــب الســجل املدنــي رقــم ( ‪ )0000‬قائــا يف دعــواه عليــه‬\n‫حيــث أنــه باإلطــاع علــى واقعــة القبــض والضبــط والتفتيــش املعــد مــن‬\n‫قبــل رجــال مكافحــة املخــدرات يتبــن أنــه يف يــوم االثنــن‬\n‫املوافق‪1433/2/15‬ه ـ ورود بــاغ مــن أحــد املصــادر الســرية عــن وجــود‬\n‫شــخص يدعى ‪ 0000/‬اجلنســية يقوم بترويج احلشــيش املخدر والتوســط‬\n‫يف ترويجــه ويســتخدم اجلــوال رقــم (‪ )0000‬ومت متكــن املصــدر مــن‬\n‫االتصــال باملدعو‪0000/‬وطلــب منــه قطعــة حشــيش مخــدر فــرد عليــه‬\n‫أنــا باجلبيــل باكلملــك واحــد مــن الدمــام يوفــر لــك احلشــيش فوافــق‬\n‫املصــدر وأعطــاه الرقــم (‪ )0000‬ومت تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا‬\n‫ـراء للذمــة وجــرى تســليمه املبلــغ احلكومــي املرقــم ومت تكليــف احــد‬     ‫إبـ ً‬\n‫رجــال األمــن مبرافقــة املصــدر وعنــد وصــول الفرقــة واملصــدر للدوحــة‬\n‫للمــكان املتفــق عليــه قــام الشــخص باالتصــال علــى املصــدر وتقابــا‬\n‫عنــد ‪ ، ......‬مســتقال ســيارة مــن نــوع ‪ ........‬حتمــل لوحــه رقــم (‪ )........‬ال‬\n‫تعــود ملكيتهــا لــه وقــام رجــل األمــن بالركــوب معــه يف ســيارته نياب ـ ًة‬\n‫عــن املصــدر وذلــك لعــدم معرفتــه باملصــدر‪ ،‬وقــام بالركــوب معــه‬\n‫والحــظ قطعــة ســوداء اللــون بيــده اليمنــى يشــتبه أن تكــون مــن مــادة‬\n‫احلشــيش املخــدر تــزن (‪ )94.3‬أربعــة وتســعني جرامـ ًا وثالثــة مــن العشــرة‬\n‫مــن اجلــرام وأثنــاء اســتالمه للمبلــغ قــام رجــل األمــن بالســيطرة عليــه بعــد‬\n‫محاولــة هروبــه واتضــح املدعــى عليــه وبتفتيــش الســيارة عثــر علــى قطعة‬\n‫ســوداء اللــون تــزن(‪ )12.3‬جــرام يشــتبه أن تكــون مــن مــادة احلشــيش‬\n‫املخــدر بداخــل الــدرج علــى ميــن الســائق أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم بالشــرقية‬\n‫برقــم (‪682‬ك ش) وتاريــخ‪1433/2 /21‬ه ـ إيجابيــة مــا ضبــط ملــادة‬\n\n\n                                                                                        ‫‪262‬‬\n\f      ‫احلشــيش املخــدر وباســتجوابه ‪ /‬أقــر بصحــة واقعــة الضبــط واقــر بأنــه‬\n      ‫اتصــل عليــه شــخص يدعــى ‪ ........‬يســكن اجلبيــل حيــث ســبق أن اشــترى‬\n      ‫منــه قطعــة حشــيش مخــدر مببلــغ (‪ )2500‬ألفــن وخمســمائة ريــال‬\n      ‫لقصــد تعاطــي احلشــيش املخــدر وأنــه بتعاطــي احلشــيش املخــدر وان‬\n      ‫‪ ........‬طلــب منــه إعطــاء مــا تبقــى مــن قطعــة احلشــيش املخــدر لشــخص‬\n      ‫ســوف يقابلــه يف الظهــران وانــه تقابــل معــه بعــد تنســيقه بهاتفــه اجلــوال‬\n      ‫مــن نــوع ‪ ........‬ذي الرقــم‪ ........‬ثــم ركــب معــه شــخص وأخــذ القطعــة يف‬\n      ‫يــده واملبلــغ كان يف يــد الشــخص إال أنــه مت ضبطــه قبــل تســليمه قطعــة‬\n      ‫احلشــيش وقبــل اســتالمه املبالــغ وأقــر بشــروعه يف ترويــج قطعــة حشــيش‬\n      ‫مخــدر وأنــه عثــر علــى قطعــة تــزن (‪ )12.3‬اثنــي عشــر جرامـ ًا وثالثــة مــن‬\n      ‫العشــرة مــن اجلــرام يف الســيارة وهــي عائــدة لــه بقصــد التعاطــي ‪ .‬وانتهــى‬\n      ‫التحقيــق إلــى توجيــه االتهــام ل ـ ‪ 0000‬بحيــازة مــا وزنــه (‪ )106.6‬مائــة‬\n      ‫إجــرام وســتة مــن العشــرة مــن اإلجــرام مــن احلشــيش املخــدر بقصــد‬\n      ‫االجتــار والتعاطــي وشــروعه يف ترويجــه وتعاطــي احلشــيش املخــدر‪.‬‬\n      ‫وذلــك لألدلــة والقرائــن التالية‪/1‬إقــراره املنــوه عنــه واملــدون علــى اللفــة‬\n      ‫رقــم(‪ /2. )12-13-14‬محضــر الضبــط والتفتيــش املــدون علــى صفحــة‬\n      ‫رقــم (‪ )13-12-11‬مــن دفتــر التحقيــق اللفــة رقــم(‪ /3.)1‬التقريــر‬\n      ‫الكيمــاوي الشــرعي املرفــق علــى اللفــة رقــم (‪ ) 23‬وبالبحــث عمــا إذا‬\n      ‫كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا أطلــب اآلتــي أو ًال ‪ :‬إثبــات مــا أســند إليــه‬\n      ‫وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واحلكــم‬\n      ‫عليــه مبــا يلــي ‪ /1:‬بعقوبــة الســجن واجللــد والغرامــة الــواردة يف الفقــرة‬\n\n\n‫‪263‬‬\n\f‫(‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات ووفقــا للمــادة (‪)59‬‬\n‫مــن ذات النظــام مــع مراعــاة تطبيــق املــادة (‪ )62‬مــن ذات النظــام‪ /2‬منعــه‬\n‫مــن الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪)56‬مــن النظــام ثاني ـ ًا ‪:‬‬\n‫احلكــم عليــه باملقتضــى الشــرعي العترافــه بتعاطــي احلشــيش املخــدر‬\n‫ثالثــا ‪ :‬مصــادرة اجلــوال الــذي يحمــل الرقــم املصنعــي ( ‪ ) 8520‬املنــوه‬\n‫عنــه وفقــا للفقــرة رقــم (‪)1‬مــن املــادة رقــم (‪ )53‬وعــدم صــرف الشــريحة‬\n‫لنفــس املتهــم وفقــا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫(‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ هــذه دعــواي وبطلبــي مــن املدعــى‬\n‫عليــه اإلجابــة أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه غيــر‬\n‫صحيــح فلــم أقــم بترويــج احلشــيش املخــدر وأنــا ال اتعاطــى احلشــيش‬\n‫املخــدر وال أي نــوع مــن املخــدرات والصحيــح أن زميلــي ‪ 0000‬كان‬\n‫يســتخدم ســيارتي يف وقــت دوامــي مبدينــة اجلبيــل ونســي أغــراض بــدرج‬\n‫ســيارتي وبعدهــا اتصــل بــي وقــال لــي انــه ناســي أغــراض بــدرج ســيارتك‬\n‫وطلــب مقابلتــي فأخبرتــه بانــي ال اســتطيع مقابلتــه ألنــي للتــو خرجــت‬\n‫مــن الــدوام وطلبــت منــه تأجيــل ذلــك لوقــت آخــر وعندمــا وصلــت‬\n‫للظهــران كلمنــي مــرة اخــرى وواعدنــي بالظهــران وبعــد ســاعة إال ربــع‬\n‫تقريبــا كلمنــي ثــم حاولــت االتصــال بــه وكان جوالــه مغلــق ويف مــرة‬\n‫أخــرى مشــغول ثــم ورد جلوالــي اتصــال آخــر مــن رقــم ال اعرفــه مــن‬\n‫شــخص يدعــى ‪ ........‬قــال لــي انــه زميــل ‪ ........‬وانــه برفقتــه ذلــك الوقــت‬\n‫وان زميلــه ‪ ........‬مشــغول مبكاملــة أخــرى وقــال لــي نتقابــل الثالثــة‬\n‫جميعــا عنــد ‪ .....‬وذهبــت بالفعــل ملكادونالــدز وأثنــاء وقــويف النتظارهــم‬\n‫تفاجــأت بشــخص يفتــح بــاب الراكــب بســيارتي ويتلفــظ علــي بألفــاظ‬\n‫ســيئة جــدا ثــم قمــت بســحب الشــخص إلــى داخــل الســيارة ألنــي ال‬\n\n\n                                                                                       ‫‪264‬‬\n\f      ‫أعــرف مــن هــو وألنــه تلفــظ بــكالم قبيــح ثــم أخبرنــي بعــد ذلــك بأنــه‬\n      ‫رجــل أمــن ومــن ثــم جــاء رجــل آخــر وفتــح بــاب الســائق وضربنــي بســاحه‬\n      ‫وتلفــظ علــي وعلمــت أنــه رجــل أمــن بعــد ذلــك ولــم أقاومهــم بعــد معرفتــي‬\n      ‫بأنهــم رجــال أمــن وأخبرونــي بأنهــم فتشــوا ســيارتي ووجــدوا بهــا قطعــة‬\n      ‫حشــيش مخــدر لكننــي ال أعلــم بهــا وال تخصنــي وقــد وقعــت علــى‬\n      ‫التحقيــق دون معرفتــي مبحتــواه خلــويف وارتباكــي وقــت القبــض وليــس‬\n      ‫علــي ســوابق هكــذا أجــاب‪ .‬وبعــد ســماع الدعــوى واإلجابــة جــرى‬\n      ‫االطــاع علــى مــا يلــي أوال‪ :‬محضــر االنتقــال والقبــض والتفتيــش املــدون‬\n      ‫علــى صفحــة رقــم (‪ )13-12-11‬مــن دفتــر التحقيــق اللفــة رقــم(‪)1‬‬\n      ‫املرفــق بــأوراق املعاملــة واملعــد مــن شــعبة مكافحــة املخــدرات بالدمــام‬\n      ‫فوجــد يتضمــن يف محتــواه أنــه تلقــوا بــاغ مــن أحــد املصــادر الســرية‬\n      ‫عــن وجــود شــخص يدعــى ‪ 0000/‬اجلنســية يقــوم بترويــج احلشــيش‬\n      ‫املخــدر والتوســط يف ترويجــه ويســتخدم اجلــوال رقــم (‪ )0000‬ومت‬\n      ‫متكــن املصــدر مــن االتصــال باملدعــو‪ 0000/‬وطلــب منــه قطعة حشــيش‬\n      ‫مخــدر فــرد عليــه أنــا باجلبيــل باكلملــك واحــد مــن الدمــام يوفــر لــك‬\n      ‫احلشــيش فوافــق املصــدر وأعطــاه الرقــم (‪ )0000‬وجــرى تســليمه املبلــغ‬\n      ‫احلكومــي املرقــم ومت تكليــف احــد رجــال األمــن مبرافقــة املصــدر‬\n      ‫وعنــد وصــول الفرقــة واملصــدر للدوحــة للمــكان املتفــق عليــه قــام‬\n      ‫الشــخص باالتصــال علــى املصــدر وتقابــا عنــد ‪ .....‬مســتقال ســيارة مــن‬\n      ‫نــوع ‪ ........‬أكــورد حتمــل لوحــه رقــم (‪ )0000‬ال تعــود ملكيتهــا لــه وقــام‬\n      ‫رجــل األمــن بالركــوب معــه يف ســيارته نيابـ ًة عــن املصــدر وذلــك لعــدم‬\n      ‫معرفتــه باملصــدر‪ ،‬وقــام بالركــوب معــه والحــظ قطعــة ســوداء اللــون‬\n      ‫بيــده اليمنــى يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر تــزن (‪)94.3‬‬\n\n\n‫‪265‬‬\n\f‫أربعــة وتســعني جرام ـ ًا وثالثــة مــن العشــرة مــن اجلــرام وأثنــاء اســتالمه‬\n‫للمبلــغ قــام رجــل األمــن بالســيطرة عليــه بعــد محاولــة هروبــه واتضــح انــه‬\n‫املدعــى عليــه وبتفتيــش الســيارة عثــر علــى قطعــة ســوداء اللــون‬\n‫تــزن(‪ )12.3‬جــرام يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر بداخــل‬\n‫الــدرج علــى ميــن الســائق ثانيــا‪ :‬أقــوال املدعــى عليــه علــى ملــف التحقيــق‬\n‫رقــم (‪ )1‬الصفحتــن (‪ )15،14‬فوجــد يتضمــن مــا نصــه‪ [ :‬ســؤال‪:‬‬\n‫كيــف مت القبــض عليــك ومــا هــي أســبابه؟ جــواب‪ :‬يوجــد شــخص‬\n‫يدعــى ‪ 0000‬باجلبيــل الصناعيــة قــام بإعطائــي قطعــة حشــيش مخــدر‬\n‫قبــل يومــن قيمتهــا ألفــن وخمســمائة ريــال حيــث قمــت بشــرائها منــه‬\n‫الســتخدامي الشــخصي وقــد اتصــل بــي واخبرنــي بأنــه يوجــد شــخص‬\n‫يريــد شــراء القطعــة فقــم ببيعهــا لــه وســوف أعوضــك بــدل منهــا فاتصــل‬\n‫بــي وشــخص وقــال لــي أنــا مرســول مــن ‪ 0000‬فواعدتــه عنــد ‪ ......‬بحــي‬\n‫‪ ........‬بالظهــران فحضــر لــي وعنــد مقابلتــه لــي قــام بالركــوب معــي‬\n‫بعدهــا مت القبــض علــي مــن رجــال املكافحــة ســؤال‪ :‬أنــت متهــم بترويــج‬\n‫قطعــة مــن احلشــيش املخــدر علــى رجــال املكافحــة؟ وكذلــك حيــازة‬\n‫قطعــة أخــرى فمــا ردك؟ جــواب‪ :‬نعــم اعتــرف باحليــازة ولكــن الترويــج‬\n‫لــم أقــم بــه ســؤال‪ :‬مــا هــو غرضــك مــن احلضــور إلــى حــي الدانــة‬\n‫وبالتحديــد املــكان الــذي تواعــدت مــع املكافحــة فيــه أو الشــخص‬\n‫الــذي اتصــل بــك ؟ وجلــب معــك قطعــة احلشــيش املروجــة؟ جــواب‪:‬‬\n‫القصــد مــن ذلــك الترويــج حســب مــا طلــب منــي املدعــو ‪ ........‬ســؤال‪:‬‬\n‫أنــت متناقــض يف أقوالــك فمــرة تقــول أننــي روجــت واألخــرى تنفــي‬\n‫الترويــج فمــاردك؟ جــواب‪ :‬ردي أننــي مظلــوم بالســالفة بكاملهــا‪ ].‬ثالثــا‪:‬‬\n‫جــرى االطــاع علــى التقريــر الكيمــاوي الشــرعي املرفــق علــى اللفــة‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫رقــم (‪ ) 23‬فوجــد يتضمــن ايجابيــة املضبوطــات ملركبــات احلشــيش‬\n      ‫املخــدر‪ .‬وتأجلــت الدعــوى إلحضــار بينــة املدعــي العــام وهــم أعضــاء‬\n      ‫محضــر القبــض والتفتيــش مــن ادراة مكافحــة املخــدرات بالدمــام‬\n      ‫ورفعــت اجللســة لذلــك ويف جلســة اخــرى حضــر املدعــي العــام ‪0000‬‬\n      ‫والســجني ‪ 000‬وأحضــر للشــهادة ‪ 000‬ســجله ‪ 0000‬وبســؤاله عمــا لديــه‬\n      ‫قــال أشــهد هلل تعالــى انــه ورد بــاغ مــن شــخص يــروج احلشــيش املخــدر‬\n      ‫وباالتصــال عليــه أفــاد انــه باجلبيــل وانــه ســوف يكلــم احــد بالدمــام و‬\n      ‫قــد أعطــي للمصــدر املقــاوم رقــم املدعــى عليــه ومت التنســيق لإلطاحــة‬\n      ‫باملدعــى عليــه ومت إعــداد خطــة الزمــة ومت تكليفي بتمثيل دور املشــتري‬\n      ‫وذلــك بواســطة املصــدر املتعــاون وعندمــا تقابلــت معــه يف املوقــع احملــدد‬\n      ‫يف حــي ‪ ........‬بالقــرب مــن صــراف بنــك ‪ ........‬توجهــت إلــى ســيارة املدعى‬\n      ‫عليــه فركبــت يف الســيارة يف مقعــد الراكــب األمامــي وســلمته املبلــغ‬\n      ‫احلكومــي املرقــم وقــدره ألفــن وخمســمائة ريــال‪ 2500‬فأخــذ املبلــغ‬\n      ‫منــي وقــام بعــده وشــاهدت القطعــة يف يــده وعندمــا انتهــى مــن عــد املبلــغ‬\n      ‫قمــت مباشــرة بإطفــاء محــرك الســيارة و أعطيــت اإلشــارة للقبــض ومت‬\n      ‫القبــض علــى املدعــى عليــه وضبــط القطعــة املروجــة ومت حتريزهــا والتي‬\n      ‫بلغ وزنها حســب محضر التحريز أربعة وتســعني جرام ًا وثالثة بالعشــرة‬\n      ‫مــن اجلــرام ثــم قمــت بتفتيــش الســيارة وعثــرت علــى قطعــة أخــرى يف‬\n      ‫علبــة نظــارة بلــغ وزنهــا حســب محضــر التحريــز اثنــى عشــر جــرام وثالثــة‬\n      ‫بالعشــرة مــن اجلــرام هــذا مــا لــدي واشــهد بــه هــذا وحضــر للشــهادة‬\n      ‫‪ 0000‬ســجله ‪ 0000‬وبســؤاله عمــا لديــه قــال أشــهد هلل تعالــى أنــي‬\n      ‫كنــت قائــد الفرقــة وقمــت باملداهمــة بعــد انتهــاء عمليــة االســتالم‬\n      ‫والتســليم وســلمني الشــاهد األول قطعــة احلشــيش املروجــة وهــي القطعــة‬\n\n\n‫‪267‬‬\n\f‫الكبيــرة التــي تقــدر بنصــف الربــع وقمــت بتحريزهــا مباشــرة ثــم‬\n‫ســلمني قطعــة صغيــرة هــذا وقــد اعتــرف املدعــى عليــه بعــد القبــض‬\n‫عليــه أن القطعــة ليســت لــه وقــد أرســله بهــا ‪ 0000‬هــذا مــا لــدي واشــهد‬\n‫بــه وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه قــال أمــا الشــهود فــا‬\n‫اعرفهــم وشــهادتهم غيــر صحيحــة هــذا وبطلبــي مــن املدعــي العــام‬\n‫تعديــا للشــاهدين احضــر كل ‪ 000 0000‬وشــهد كل واحــد منهــا‬\n‫منفــردا قائــا اشــهد هلل تعالــى بعدالــة وثقــة الشــاهدين هكــذا شــهدا‬\n‫ورفعــت اجللســة للتأمــل ويف جلســة اخــرى حضــر املدعــي العــام ‪0000‬‬\n‫والســجني ‪00000‬هــذا وبســؤال املدعــي العــام زيــادة بينــة قــال ليــس لــدي‬\n‫زيــادة علــى مــا ســبق فبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة و حيــث‬\n‫أنكــر املدعــى عليــه التهمــة املوجهــة إليــه و أنكــر قيامــه بالشــروع يف‬\n‫الترويــج و حيــث ليــس للمدعــي العــام زيــادة بينــة و حيــث لــم يشــهد علــى‬\n‫اســتالم املدعــى عليــه للمبلــغ احلكومــي املرقــم و القيــام بعــد املبلــغ‬\n ‫ٍ‬\n‫كاف‬        ‫والشــروع يف عمليــة الترويــج إال شــاهد واحــد فقــط و هــذا غيــر‬\n‫للثبــوت الشــرعي لــذا لــم يثبــت لــدي شــرعا إدانتــه بالشــروع يف ترويــج‬\n‫قطعــة احلشــيش املخــدر لعــدم اكتمــال نصــاب الشــهادة و لــم يثبــت لــدي‬\n‫إدانتــه بتعاطــي احلشــيش املخــدر و ال قصــد الترويــج لعــدم قيــام البينــة‬\n‫علــى ذلــك و تتوجــه عليــه التهمــة يف قيامــه يف الشــروع يف ترويــج قطعــة‬\n‫احلشــيش املخــدر و ذلــك لشــهادة ‪ 0000‬و هــي شــهادة موصلــة يف قيــام‬\n‫املدعــى عليــه يف الشــروع يف ترويــج قطعــة احلشــيش املخــدر املضبوطــة و‬\n‫احملــرزة و تتوجــه عليــه التهمــة أيضــا يف تعاطــي احلشــيش املخــدر بقرينــة‬\n‫أقوالــه علــى ملــف التحقيــق الــذي رجــع عنــه و حكمــت عليــه مبــا يلــي ‪:‬‬\n‫[‪ ]1‬درء حــد املســكر عنــه و ذلــك لرجوعــه عــن إقــراره بتعاطي احلشــيش‬\n\n\n                                                                                       ‫‪268‬‬\n\f      ‫املخــدر و تعزيــره علــى التهمــة يف تعاطــي احلشــيش املخــدر بجلــده ســتني‬\n      ‫جلــدة دفعــة واحــدة علنــا و يف مــكان عــام [‪ ]2‬تعزيــر املدعــى عليــه علــى‬\n      ‫التهمــة املوجهــة إليــه يف الشــروع يف ترويــج احلشــيش املخــدر بســجنه‬\n      ‫ســنتني تبــدأ اعتبــارا مــن تاريــخ ســجنه و جلــده مائتــن و خمســن جلــدة‬\n      ‫مفرقــة علــى خمــس دفعــات متســاويات بــن كل دفعــة و األخــرى أســبوع‬\n      ‫علنــا و يف مــكان عــام ويفــرق بــن جلــد التعزيــر علــى التعاطــي و جلــد‬\n      ‫التعزيــر علــى تهمــة الشــروع يف الترويــج بأســبوع [‪ ]2‬رد مطالبــة املدعــي‬\n      ‫العــام معاقبتــه وفقــا للفقــرة األولــى مــن املــادة (‪ )38‬لعــدم ثبــوت الترويــج‬\n      ‫و ال الشــروع يف الترويــج و ال احليــازة بقصــد الترويــج [‪ ]3‬رد مطالبــة‬\n      ‫املدعــى عليــه مــن الســفر وفقــا للفقــرة األولــى مــن املــادة (‪ )56‬لعــدم‬\n      ‫ثبــوت التعاطــي و احليــازة و الترويــج [‪ ]4‬رد مطالبــة املدعــي العــام‬\n      ‫مبصــادرة اجلــوال العائــد للمدعــى عليــه وفقــا للفقــرة األولــى مــن املــادة‬\n      ‫(‪ )53‬لعــدم ثبــوت الترويــج و ال الشــروع يف الترويــج و ال احليــازة بقصــد‬\n      ‫الترويــج وبعــرض احلكــم عليهــم قــرر املدعــي العــام املعارضــة وقــرر‬\n      ‫اكتفائــه بالئحــة الدعــوى عــن تقــدمي الئحــة اعتراضيــة وقــرر املدعــى‬\n      ‫عليــه عــدم القناعــة وطلــب التمييــز فأفهــم بــأن مــدة االعتــراض ثالثــون‬\n      ‫يومــا تبــدأ بعــد مهلــة تنظيــم القــرار عشــرة أيــام إذا مضــت املــدة ولــم‬\n      ‫يعتــرض ســقط حقــه يف طلــب التمييــز وترفــع املعاملــة حملكمــة‬\n      ‫االســتئناف بــدون الئحــة خــال خمســة وأربعــن يومــا مــن تاريــخ هــذا‬\n      ‫اليــوم ولــه املراجعــة خــال املهلــة واملــدة النظامية الســتالم نســخه احلكم‬\n      ‫لالعتــراض عليــه وصلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم‬\n                                                              ‫حرر يف ‪1433 /6/9‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ 0000‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n‫‪269‬‬\n\f‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ ........‬وتاريــخ ‪1433/04/03‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ ........‬وتاريــخ ‪ 1433/04/03‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1433/06/18‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 23‬‬\n‫وفيهــا حضــر املدعــى عليــه وأقــر بقناعتــه باحلكــم وقــال أنــي ال أرغــب‬\n‫يف تقــدمي اعتــراض هكــذا أقــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n        ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/18‬ه ـ ‪.‬‬\n‫احلمــد هلل و حــده وبعــد ففــي يــوم الثالثــاء املوافق ‪1433 /9/5‬هـ الســاعة‬\n‫‪ 12.00‬افتتحــت اجللســة املتعلقــة بدعــوى املدعــي العــام ضــد ‪ 0000‬وقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف برقــم ‪ 000‬يف ‪1433 /8/24‬ه ـ‬\n‫وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى برقــم‬\n‫‪ 0000‬يف ‪1433 /8/18‬ه ـ ونــص احلاجــة منــه ‪ ،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة لوحــظ أن صــورة الضبــط ناقصــة ‪،‬عليــه أجيــب‬\n‫أصحــاب الفضيلــة أنــه ســبق للمدعــى عليــه القناعــة باحلكــم ولــم يتــم‬\n‫التهميــش علــى القــرار الشــرعي بذلــك لــذا فقــد مت إرفــاق صــورة ضبــط‬\n‫كامــل القضيــة كمــا ســيتم التهميــش علــى القــرار بقناعــة املدعــى‬\n‫عليــه باحلكــم و مبضمــون هــذه اجللســة وصلــى اهلل علــى نبينــا محمــد‬\n                               ‫وآلــه وصحبــه وســلم حــرر يف ‪1433 /9/5‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم االثنــن املوافــق ‪1433/11/29‬ه ـ‬\n‫الســاعة ‪ 11.30‬افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫الســجني وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫‪0000‬وتاريــخ ‪1433/11/3‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة‬\n‫الدائــرة اجلزائيــة الثالثيــة األولــى رقــم ‪ 00000‬وتاريــخ ‪1433/10/23‬ه ـ‬\n\n\n                                                                                  ‫‪270‬‬\n\f      ‫ونــص احلاجــة منــه ‪ ،‬لوحــظ أن املدعــى عليــه قــد أقــر لــدى فضيلتــه‬\n      ‫بأنــه اســتخرج قطعــة احلشــيش مــن ســيارته و نفــى علمــه بهــا و الشــخص‬\n      ‫مســئول عمــا حتــت يــده و هــو مؤاخــذ بإقــراره و هــذا يرقــى إلــى إدانــة‬\n      ‫املدعــى عليــه باحليــازة املجــردة للحشــيش املخــدر ‪ ،‬هــذا و لوجاهــة مــا‬\n      ‫ذكــره أصحــاب الفضيلــة فقــد رجعــت عما حكمت به ســابقا و ذلك ملا‬\n      ‫ســبق ذكــره وحيــث أقــر املدعــى عليــه بــأن رجــال األمــن فتشــوا الســيارة‬\n      ‫و عثــروا علــى قطعــة احلشــيش بالســيارة و نفــى علمــه بهــا و حيــث شــهد‬\n      ‫الشــاهد ‪ ........‬أنــه شــاهد القطعــة يف يــده و حيــث شــهد ‪ ........‬باعتــراف‬\n      ‫املدعــى عليــه بعــد القبــض عليــه أن القطعــة ليســت لــه وقــد أرســله بهــا‬\n      ‫‪ ........‬و هــذا كاف يف إثبــات إدانتــه بحيــازة قطعــة احلشــيش املخــدر دون‬\n      ‫إثبــات القصــد مــن احليــازة و حيــث أنكــر املدعــى عليــه قيامــه بالشــروع‬\n      ‫يف الترويــج و حيــث ليــس للمدعــي العــام زيــادة بينــة و حيــث لــم يشــهد‬\n      ‫علــى اســتالم املدعــى عليــه للمبلــغ احلكومــي املرقــم و القيــام بعــد املبلــغ‬\n        ‫ٍ‬\n      ‫كاف‬       ‫و الشــروع يف عمليــة الترويــج إال شــاهد واحــد فقــط و هــذا غيــر‬\n      ‫للثبــوت الشــرعي و حيــث أن احملكمــة ال تتقيــد بالوصــف الــوارد‬\n      ‫بالئحــة الدعــوى وعليهــا أن تعطــي الفعــل الوصــف الــذي يســتحقه وذلــك‬\n      ‫حســب نــص املــادة (‪ )159‬مــن نظــام اإلجــراءات اجلزائيــة و ملــا تضمنتــه‬\n      ‫املــادة (‪ )39‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فقــد‬\n      ‫ثبــت لــدي شــرعا إدانــة املدعــى عليــه بحيــازة املخــدرات ولــم يثبــت لــدي‬\n      ‫قصــده مــن احليــازة ألن القصــد مــن أعمــال القلــوب التــي ال تعلــم إال‬\n      ‫بإقــرار أو بينــة دالــة عليــه كمــا لــم يثبــت لــدي شــرعا إدانتــه بالشــروع‬\n      ‫يف ترويــج قطعــة احلشــيش املخــدر لعــدم اكتمــال نصــاب الشــهادة و لــم‬\n      ‫يثبــت لــدي إدانتــه بتعاطــي احلشــيش املخــدر و تتوجــه عليــه التهمــة يف‬\n\n\n‫‪271‬‬\n\f‫قيامــه يف الشــروع يف ترويــج قطعــة احلشــيش املخــدر و ذلــك لشــهادة‬\n‫‪ ........‬و هــي شــهادة موصلــة يف قيــام املدعــى عليــه يف الشــروع يف ترويــج‬\n‫قطعــة احلشــيش املخــدر املضبوطــة و احملــرزة و تتوجــه عليــه التهمــة‬\n‫أيضــا يف تعاطــي احلشــيش املخــدر بقرينــة أقوالــه علــى ملــف التحقيــق‬\n‫الــذي رجــع عنــه و حكمــت عليــه مبــا يلــي‪ ]1[ :‬درء حــد املســكر عنــه‬\n‫و ذلــك لرجوعــه عــن إقــراره بتعاطــي احلشــيش املخــدر و تعزيــره علــى‬\n‫التهمــة يف تعاطــي احلشــيش املخــدر بجلــده ســتني جلــدة دفعــة واحــدة‬\n‫علنــا و يف مــكان عــام [‪ ]2‬تعزيــر املدعــى عليــه علــى حيــازة قطعــة‬\n‫احلشــيش املخــدر حيــازة مجــردة وفقــا للمــادة (‪ )39‬مــن نظــام مكافحــة‬\n‫املخــدرات بســجنه ســنتني تبــدأ اعتبــارا مــن تاريــخ ســجنه و جلــده مائتــن‬\n‫و خمســن جلــدة مفرقــة علــى خمــس دفعــات متســاويات بــن كل دفعــة‬\n‫واألخــرى أســبوع علنــا و يف مــكان عــام ويفــرق بــن جلــد التعزيــر علــى‬\n‫التعاطــي و جلــد التعزيــر علــى احليــازة املجــردة بأســبوع وتغرميــه أربعــة‬\n‫آالف ريــال تــودع يف خزينــة الدولــة و تصــرف يف املصــارف العامــة [‪]3‬‬\n‫منــع املدعــى عليــه مــن الســفر وفقــا للفقــرة األولــى مــن املــادة (‪ )56‬مــدة‬\n‫ســنتني تبــدأ اعتبــار مــن خروجــه مــن الســجن [‪ ]4‬أن تعزيــره علــى التهمــة‬\n‫املوجهــة إليــه يف الشــروع يف ترويــج احلشــيش املخــدر داخــل يف تعزيــره‬\n‫علــى احليــازة املجــردة [‪ ]5‬رد مطالبــة املدعــي العــام معاقبتــه وفقــا للفقــرة‬\n‫األولــى مــن املــادة (‪ )38‬لعــدم ثبــوت الترويــج و ال الشــروع يف الترويــج و ال‬\n‫احليــازة بقصــد الترويــج [‪ ]4‬رد مطالبــة املدعــي العــام مبصــادرة اجلــوال‬\n‫العائــد للمدعــى عليــه وفقــا للفقــرة األولــى مــن املــادة (‪ )53‬لعــدم ثبــوت‬\n‫الترويــج و ال الشــروع يف الترويــج و ال احليــازة بقصــد الترويــج وبعــرض‬\n‫احلكــم عليهــم قــرر املدعــى عليــه القناعــة بــه و قــرر املدعــي العامــة عــدم‬\n\n\n                                                                                       ‫‪272‬‬\n\f      ‫املعارضــة وصلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم حــرر يف‬\n                                                                       ‫‪1433/11/29‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم ‪0000‬‬\n      ‫وتاريــخ ‪1434/1/4‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪/34/45581‬ج‪1‬‬\n      ‫وتاريــخ ‪1434/1/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪ 0000‬املســجل برقــم ‪ 0000‬وتاريــخ ‪1433/6/10‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــى العــام ضــد‪ 000/‬يف قضيــة مخــدرات وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬حيــث‬\n      ‫ســبق دراســة القــرار وصــورة ضبطــه وباإلطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‪/‬‬\n      ‫ج‪/1‬ب يف ‪1433/10/23‬ه ـ قررنــا املصادقــه علــى احلكــم بعــد االجــراء‬\n      ‫االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                             ‫حــرر يف ‪1434/1/11‬ه ـ ‪.‬‬\n\n\n\n\n‫‪273‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":260,"source_page_end":273,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ca3a75f955a128bbf2ac66ef40819573571b11fda1d4aa7d21137086588fc723","normalized_text_hash":"a62633c593fe22d9b3de814bef78de683fa12b53e65ea46218809d54f1a86d84","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p260-33292678"},{"id":"3f973cc5-ca5b-5582-9a84-73a71bd09282","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واملنع من السفر .","document_number":"33366603","case_number":"33266519","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":"الدائرة اجلزائية الثانية واملتعلقة بدعوى املدعي العام ضد واملتضمن","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/04","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33366603:‬تاريخه ‪1433/08/04 :‬هـ‬\n                   ‫رقم الدعوى ‪33266519 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪34487954‬تاريخه‪1434/07/30:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬حــد املســكر‬\n ‫‪ -‬إقــرار‪ -‬إدانــة ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر بالســجن‬\n                                                       ‫واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬كل مســكر خمــر وكل خمــر‬\n                                                     ‫حــرام)‪ .‬رواه مســلم‬\n                              ‫‪ -2‬املادة (‪ )6‬من نظام اإلجراءات اجلزائية‪.‬‬\n ‫‪ -3‬املــواد (‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                               ‫العقليــة‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n ‫بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع من الســفر طبقا‬\n ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه مت تفتيــش‬\n ‫ســيارته بعــد االشــتباه بهــا فعثــر فيهــا علــى احلشــيش املخــدر وأثبــت‬\n ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش‬\n ‫املخــدر‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪،‬‬\n ‫وحيــث إن املدعــى عليــه أبــدى التوبــة وال يوجــد لــه ســوابق‪ ،‬فقضــت‬\n\n                                                                                     ‫‪280‬‬\n\f      ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت ســجنه‬\n      ‫ملــدة ثالثــة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني وجلــده‬\n      ‫ثمانــن جلــدة حــدا دفعــة واحــدة علنــا‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                       ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بتبوك‪/‬املســاعد برقــم ‪ 33266519‬وتاريــخ ‪ 1433/04/17‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33718233‬وتاريــخ ‪ 1433/04/17‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافــق ‪1433/07/28‬ه ـ افتتحــت اجللســة الســاعة ‪01 :00‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ........‬وادعــى علــى احلاضــر معــه يف املجلــس الشــرعي ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬قائــا يف دعــواه‬\n      ‫أنــه يف تاريــخ أنــه بتاريــخ ‪1433/2/22‬ه ـ وأثنــاء قيــام فرقــة مكافحــة‬\n      ‫املخــدرات بجولتهــا املعتــادة داخــل وخــارج احملافظــة مت االشــتباه بســيارة‬\n      ‫مــن نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪ )....‬تقــف علــى الكرنيــش وعنــد‬\n      ‫االقتــراب منهــا ظهــر علــى قائدهــا االرتبــاك وبتفتيشــه شــخصيا لــم يعثــر‬\n      ‫معــه علــى شــيء مــن املمنوعــات وبتفتيــش الفرشــة التــي يجلــس عليهــا‬\n      ‫عثــر علــى كيــس نايلــون وبداخلــه قطعتــان بحجــم اإلصبــع ســوداء اللــون‬\n      ‫بلــغ وزنهــا عشــرة جــرام ومائــة مليجــرام يشــتبه أن تكــون مــن احلشــيش‬\n      ‫املخــدر كمــا عثــر علــى ورق لــف فتــم القبــض عليــه وإيداعــه للتوقيــف‬\n\n‫‪281‬‬\n\f‫حلــن اســتكمال التحقيــق معــه أثبــت التقريــر الكيميائــي الشــرعي‬\n‫الصــادر مــن مركــز الســموم والكيميــاء الطبيــة بصحــة تبــوك رقــم‬\n‫(‪ )........‬لعــام ‪1433/2/2‬ه ـ إيجابيــة عينــة مــا مت ضبطــه للحشــيش‬\n‫املخــدر وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة املنــوه عنــه باجلــدول‬\n‫الثانــي فئــة (أ) مــن تعميــم صاحــب الســمو امللكــي النائــب الثانــي‬\n‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )89400/19‬وتاريــخ‬\n‫‪1426/10/25‬ه ـ كمــا أثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n‫مــن مركــز الســموم والكيميــاء الطبيــة بصحــة تبــوك رقــم(‪)........‬‬\n‫وتاريــخ ‪1433/3/19‬ه ـ إيجابيــة عينــة البــول املــادة الفعالــة للحشــيش‬\n‫املخــدر وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة املنــوه عنــه باجلــدول‬\n‫الثانــي فئــة (أ) مــن تعميــم صاحــب الســمو امللكــي النائــب الثانــي‬\n‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )89400/19‬وتاريــخ‬\n‫‪1426/10/25‬ه ـ وباســتجواب املدعــى عليــه بعــد إحاطتــه علمـ ًا بالتهمــة‬\n‫املنســوبة إليــه واجلهــة التــي تباشــر اســتجوابه أقــر بصحــة واقعــة الضبــط‬\n‫وبعائدية الكمية املضبوطة له بقصد االســتعمال الشــخصي وملا أشــير‬\n‫إليــه أقــرر توجيــه االتهــام للمدعــى عليــه بحيــازة قطعتــن مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا عشــرة جــرام ومائــة مليجــرام بقصــد التعاطــي وذلــك‬\n‫لألدلــة والقرائــن التاليــة ‪-1‬اعترافــه املنــوه املــدون علــى الصفحــة رقــم‬\n‫(‪ )2-1‬مــن محضــر الضبــط لفــة رقــم (‪-2 )9‬محضــر القبــض املنــوه عنــه‬\n‫املرفــق لفــة رقــم (‪-3 )1‬التقريريــن الكيميائيــن الشــرعيني املرفقــن‬\n‫علــى اللفــات رقــم (‪ )16-18‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n‫ســوابق جنائيــة مســجلة حتــى تاريخــه وحيــث أن مــا أقــدم عليــه املذكــور‬\n‫ـرم شــرعا ومجــرم نظامــا لــذا أطلــب مــا يلــي ‪ -1‬إثبــات مــا‬     ‫فعــلٌ محـ ٌ‬\n\n                                                                                        ‫‪282‬‬\n\f      ‫أســند إليــه ‪ -2‬احلكــم عليــه بالســجن وفقــا للمــادة (‪ )41‬قفــرة (‪)1‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه أغــاه‬\n      ‫‪ -3‬املنــع مــن الســفر خــارج البلــد وفقــا للمــادة ‪ 56‬فقــرة (‪ )1‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه أعــاه هــذه دعــواي‬\n      ‫وبعــرض الدعــوى علــى املدعــى عليــه وســؤاله عنهــا أجــاب بقولــه مــا جــاء‬\n      ‫يف دعــوى املدعــي العــام صحيــح جملــة وتفصيــا وأصــادق عليــه وأنــا‬\n      ‫تائــب توبــة نصوحــا مــن ســلوك طريــق املخــدرات هــذه إجابتــي وجــرى‬\n      ‫االطــاع علــى التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n      ‫مراقبــة الســموم والكيميــاء التابــع للشــؤون الصحيــة مبنطقــة تبــوك‬\n      ‫وجدتــه يتضمــن إيجابيــة مــا مت ضبطــه مــع املدعــى عليــه للحشــيش‬\n      ‫املخــدر هكــذا تضمــن فبنــاء علــى الدعــوى واإلجابــة باملصادقــة علــى‬\n      ‫كل مــا جــاء يف الدعــوى وألن النبــي صلــى اهلل عليــه وســلم قــال كل‬\n      ‫مســكر خمــر وكل خمــر حــرام رواه مســلم وبنــاء علــى اطالعــي علــى‬\n      ‫املادتــن (‪ )56-41‬مــن نظــام مكافحــة املخــدرات واطالعــي علــى املــادة‬\n      ‫‪ 60‬مــن نظــام مكافحــة املخــدرات ولكــون املدعــى عليــه ليــس لديــه‬\n      ‫ســوابق جنائيــة مســجلة وأفــاد بأنــه تائــب توبــة نصوحــا لهــذا كلــه ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫عشــرة جرامــات ومائــة مليجــرام بقصــد التعاطــي وحكمــت عليــه‬\n      ‫مبــا يلــي أوال تعزيــر املدعــى عليــه بســجنه ثالثــة أشــهر يحتســب منهــا‬\n      ‫مــدة إيقافــه لقــاء حيازتــه للحشــيش املخــدر ثانيــا منــع املدعــى عليــه‬\n      ‫مــن الســفر خــارج اململكــة العربيــة الســعودية مــدة ســنتني مــن تاريــخ‬\n      ‫انتهــاء مــدة ســجنه وبعــرض احلكــم علــى املدعــى عليــه قنــع بــه وبعــرض‬\n      ‫احلكــم علــى املدعــي العــام قــرر عــدم قناعتــه باحلكــم وطلــب رفعــه‬\n\n\n‫‪283‬‬\n\f‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه لطلبــه وعليــه‬\n‫جــرى رفــع اجللســة بعــد افتتاحهــا بنصــف ســاعة لرفــع املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم حســب املتبــع وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/8/3‬ه ـ احلمــد هلل وحــده وبعــد‬\n‫ثــم أنــه يف يــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ افتحــت اجللســة الســاعة‬\n‫الثامنــة وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة تبــوك‬\n‫مبوجــب اخلطــاب رقــم ‪ 331668594‬وتاريــخ ‪1433/9/20‬ه ـ املتضمــن‬\n‫قــرار املالحظــة رقــم ‪ 33412995‬وتاريــخ ‪1433/9/17‬ه ـ الصــادر مــن‬\n‫الدائــرة اجلزائيــة الثانيــة واملتعلقــة بدعــوى املدعــي العــام ضــد واملتضمــن‬\n‫مــا نصــه‪ ( :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا‬\n‫يلــي‪ :‬أوال‪ :‬لــم يذكــر فضيلتــه خطــاب تكليــف املدعــي العــام بالترافــع‬\n‫ثانيــا‪ :‬لــم يســأل فضيلتــه املدعــى عليــه عــن اســتعماله للحشــيش املخــدر‬\n‫ولــم يجــر شــيئا جتــاه ذلــك ملالحظــة ذلــك وإحلــاق مــا يجريــه علــى الضبــط‬\n‫والقــرار وصورتــه حســب التعليمــات) وعليــه أجيــب أصحــاب الفضيلــة‬\n‫الكــرام أمــا املالحظــة األولــى فــإن رقــم خطــاب تكليــف املدعــي العــام‬\n‫هــو‪ 9813‬وتاريــخ ‪1431/7/14‬ه ـ الصــادر مــن رئيــس هيئــة التحقيــق‬\n‫واالدعــاء العــام مبنطقــة تبــوك أمــا املالحظــة الثانيــة فأجيــب أصحــاب‬\n‫الفضيلــة األعــزاء أنــه باالطــاع علــى الئحــة املدعــي العــام لــم أجــد فيهــا‬\n‫توجيــه االتهــام مــن املدعــي العــام للمدعــى عليه بتعاطي احلشــيش املخدر‬\n‫كمــا أن التحقيــق مــع املدعــى عليــه لــم يوجــد فيــه إقــرار للمدعــى عليــه‬\n‫بتعاطــي احلشــيش املخــدر وعليــه جــرى رفــع اجللســة بعــد افتتاحهــا بربــع‬\n‫ســاعة لرفــع املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب‬\n‫املتبــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n\n\n                                                                                       ‫‪284‬‬\n\f      ‫‪ 1434/01/06‬ه ـ احلمــد هلل وحــده وبعــد ثــم انــه يف يــوم الثالثــاء املوافــق‬\n      ‫‪1434/6/20‬ه ـ فتحــت اجللســة املتعلقــة بدعــوى املدعــي العــام ضــد يف‬\n      ‫قضيــة مخــدرات وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة‬\n      ‫تبــوك مبوجــب اخلطــاب رقــم ‪ 34487954‬وتاريــخ ‪1434/4/22‬ه ـ‬\n      ‫واملتضمــن قــرار املالحظــة ‪ 34189120‬وتاريــخ ‪1434/4/16‬ه ـ الصــادر‬\n      ‫مــن الدائــرة اجلزائيــة الثانيــة واملتضمــن مــا نصــه (باالطــاع علــى مــا‬\n      ‫أجــاب بــه فضيلتــه علــى الفقــرة الثانيــة منــه وجــد غيــر وجيــه وال يتفــق‬\n      ‫مــع مــا طلــب منــه حيــث نصــت امللحوظــة علــى أن فضيلتــه لــم يســأل‬\n      ‫املدعــى عليــه عــن اســتعماله للحشــيش املخــدر مــع أنــه مقــر بحيازتــه لــه‬\n      ‫لالســتعمال كمــا أن للمحكمــة أن حتكــم يف وقائــع غيــر مدعــي بهــا‬\n      ‫مــن املدعــي العــام فيمــا ال يحتــاج إلــى حتقيــق طبقــا للمــادة السادســة‬\n      ‫مــن نظــام اإلجــراءات ال ســيما وقــد أثبــت التقريــر الكيمائــي الشــرعي‬\n      ‫املشــار إليــه يف الئحــة الدعــوى املتضمــن إيجابيــة عينة البــول أليض املادة‬\n      ‫الفعالــة لتعاطــي احلشــيش املخــدر املرفــق علــى لفــة رقــم ‪ 18‬مــع التنبيــه‬\n      ‫إلــى أن لــم يشــر لصحيفــة ســوابقه ومضمونهــا وموضعهــا باملعاملــة وإلــى‬\n      ‫أنــه ورد يف تســبيب فضيلتــه ســياق حديــث كل مســكر خمــر وكل‬\n      ‫خمــر حــرام فمــا وجــه إيــراده يف مقــام إثبــات احليــازة للحشــيش إذ ال يــرد‬\n      ‫ذلــك إال يف مقــام االســتدالل إلقامــة احلــد يف تعاطــي احلشــيش وذكــر‬\n      ‫اســم املوثــق لصــورة الضبــط طبــق أصلهــا ملالحظــة ذلــك وإحلــاق مــا‬\n      ‫يجريــه علــى الضبــط والقــرار وصورتــه حســب التعليمــات واهلل املوفــق)‬\n      ‫وعليــه أجيــب أصحــاب الفضيلــة أمــا املالحظــة األولــى فقــد جــرى ســؤال‬\n      ‫املدعــى عليــه هــل تتعاطــى احلشــيش املخــدر فأجــاب بقولــه نعــم كنــت‬\n      ‫أتعاطــي احلشــيش املخــدر وقــد تبــت مــن تعاطيــه هــذه إجابتــي وعليــه‬\n\n\n‫‪285‬‬\n\f‫فقــد ثبــت لــدي إدانــة املدعــي بتعاطــي احلشــيش املخــدر إضافــة إلــى مــا‬\n‫ثبــت مــن حيازتــه للحشــيش املخــدر وحكمــت عليــه بجلــده ثمانــن جلــدة‬\n‫حــدا دفعــة واحــدة علنــا لقــاء تعاطيــه احلشــيش املخــدر أمــا املالحظــة‬\n‫الثانيــة فقــد جــرى الرجــوع إلــى صحيفــة الســوابق علــى اللفــة رقــم ‪21‬‬\n‫ولــم أجــد فيهــا ســوابق مســجلة علــى املدعــى عليــه أمــا بقيــة املالحظــات‬\n‫فقــد جــرى التنبيــه لهــا وإكمــال الــازم حيالهــا وبعــرض احلكــم علــى‬\n‫الطرفــن قنــع بــه املدعــى عليــه ولــم يقنــع املدعــي العــام وطلــب رفــع‬\n‫احلكــم حملكمــة االســتئناف فأجبتــه لطلبــه وعليــه جــرى رفــع اجللســة‬\n‫بعــد افتتاحهــا بنصــف ســاعة وحــرر يف ‪1434/6/20‬ه ـ وصلــى اهلل‬\n                                                     ‫وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــدهلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بتبــوك برقــم ‪ 33266519‬وتاريــخ ‪ 1433/4/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33718233‬وتاريــخ ‪ 1433/4/17‬هـ ففي يوم االربعاء‬\n‫املوافــق ‪ 1434/8/17‬ه ـ افتتحــت اجللســة الســاعة الواحــدة ظهــر ًا وفيهــا‬\n‫عــادت املعاملــة مــن محكمــة اإلســتئناف مبنطقــة تبــوك مبوجــب‬\n‫خطــاب رئيســها رقــم ‪ 34487954‬وتاريــخ‪ 1434/7/30‬ه ـ املتضمــن‬\n‫قــرار املصادقــة رقــم ‪ 34275999‬وتاريــخ ‪ 1434/7/23‬ه ـ الصــادر مــن‬\n‫الدائــرة اجلزائيــة الثانيــة املتضمــن دعــوى املدعــي العــام ضــد ‪ ......‬املتهــم‬\n‫يف قضيــة مخــدرات لذلــك جــرى التهميــش يف ضبطــه وإرســال املعاملــة‬\n‫لإلمــارة حســب املتبــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                            ‫وســلم‪ .‬حــرر يف يــوم االربعــاء ‪ 1434/08/17‬ه ـ ‪.‬‬\n\n\n\n                                                                                        ‫‪286‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":280,"source_page_end":286,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8effe9af49460c581162be55cc1dcc88470e90b9634162f8c40a4d64be5a6a8e","normalized_text_hash":"94b14e4c3c4feea494da2bf426d576e5ace22d05aef3701ef736295912c4b236","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p280-33366603"},{"id":"60bee6dc-d326-58ae-a302-3ce299bf49ad","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة باحليازة املجردة عن القصد -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد واملنع من السفر والغرامة.","document_number":"33275897","case_number":"33272516","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/04/19","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة باحليازة املجردة عن القصد -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد واملنع من السفر والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33275897:‬تاريخه‪1433/04/19 :‬هـ‬\n                          ‫رقم الدعوى‪33272516:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34186927‬تاريخه‪1433/04/14 :‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬عــدم التقيــد‬\n       ‫بالوصــف الــوارد يف الئحــة الدعــوى ‪ -‬إدانــة باحليــازة املجــردة عــن‬\n       ‫القصــد ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد‬\n                                                   ‫واملنــع مــن الســفر والغرامــة‪.‬‬\n\n\n\n\n                                  ‫‪ -1‬املادة (‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n       ‫‪ -2‬املــواد (‪ )39‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة‪.‬‬\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر لقصــد التعاطــي وتعاطيــه لــه‪ ،‬واحلكــم عليــه‬\n       ‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n       ‫واملؤثــرات العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى‬\n       ‫قطعــة مــن احلشــيش املخــدر أســفل مقــود الســيارة‪ ،‬أثبــت التقريــر‬\n       ‫الكيميائــي الشــرعي إيجابيــة العينة املرســلة للحشــيش املخدر‪ ،‬أنكر‬\n       ‫أمــام احملكمــة مــا أســنده إليــه املدعــي العــام وأقــر بــأن احلشــيش املخــدر‬\n       ‫ضبــط يف ســيارته وال يعلــم ملــن يعــود‪ ،‬املدعــى عليــه لــم يقــر بقصــد‬\n\n‫‪287‬‬\n\f‫االســتعمال مــن احليــازة ولــم تقــم بينــة علــى ذلــك‪ ،‬قضــت احملكمــة‬\n‫بإدانتــه بحيــازة احلشــيش املخــدر حيــازة مجــردة وبــرد دعــوى املدعــي‬\n‫العــام بطلــب إدانتــه بحيــازة احلشــيش لقصــد االســتعمال واســتعماله لــه‬\n‫وقــررت ســجنه ملــدة ســتة أشــهر وجلــده خمســن جلــدة دفعــة واحــدة علنــا‬\n‫يف مــكان عــام ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني وتغرميــه‬\n‫مبلــغ ثالثــة آالف ريــال‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي‬\n     ‫العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ........‬القاضــي يف احملكمــة اجلزئيــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة يف محافظــة اخلبــر برقــم ‪ 33272516‬وتاريــخ ‪1433/04/19‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33735643‬وتاريــخ ‪1433/04/19‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق ‪1433/05/11‬ه ـ افتتحــت اجللســة الســاعة ‪11 :04‬‬\n‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره الســجني‪ .......‬ســجله (‪).......‬‬\n‫وادعــى املدعــي العــام‪ .......‬قائــا يف حتريــر دعــواه حيــث أنــه باالطــاع‬\n‫علــى محضــر إيضاحــات واقعــة القبــض املعــد مــن قبــل مكافحــة‬\n‫ـاء يــوم األربعــاء‬\n                 ‫املخــدرات تبــن أنــه يف حوالــي الســاعة العاشــرة مــن مسـ ً‬\n‫املوافــق ‪ 1433/3/16‬ه ـ وردهــم بــاغ مــن أحد مصادرهم الســرية مفاده‬\n‫وجــود منــزل بــ‪ .....‬تتــردد عليــه ســيارات ألشــخاص يشــتبه أنهــم يقومــون‬\n‫ا مت‬‫بتعاطــي املخــدرات ‪ ،‬ويف حوالــي الســاعة العاشــرة والنصــف لي ـ ً‬\n‫االنتقــال إلــى املوقــع املبلــغ عنــه ‪ ،‬وعنــد الوصــول لوحظــت ســيارة مــن‬\n‫نــوع ‪ .....‬خضــراء اللــون حتمــل اللوحــة رقــم (‪ ).....‬تقــف بجانــب املنــزل ‪،‬‬\n\n                                                                                     ‫‪288‬‬\n\f      ‫وبعــد دقيقتــن حتركــت الســيارة وقامــت الدوريــة مبتابعتهــا عــن بعــد‬\n      ‫إلــى أن توقفــت بجانــب أحــد احملــات اإللكترونيــة علــى شــارع ‪ .....‬بــ‪.....‬‬\n      ‫وعنــد نــزول الســائق قامــوا بالتوجــه إليــه وطلــب إثباتــه فأفاد بعــدم حمله‬\n      ‫إلثباتــه وبتفتيشــه وتفتيــش مركبتــه عثــر علــى قطعــة ســمراء اللــون يف‬\n      ‫الــدرج الواقــع أســفل مقــود الســيارة تــزن (‪ )0.4‬أربعــة مــن العشــرة مــن‬\n      ‫اجلــرام أثبــت التقريــر الكيمــاوي الشــرعي ملراقبــة الســموم الصــادر‬\n      ‫برقــم (‪ 1104‬ك ش ) وتاريــخ ‪1433/3/23‬ه ـ إيجابيــة العينــة املضبوطــة‬\n      ‫ملــادة احلشــيش املخــدر و احملظــور وباســتجوابه ‪ /‬أقــر بصحــة واقعــة‬\n      ‫القبــض عليــه أثنــاء وقوفــه عنــد محــل إلكترونيات وأنه عثــر على قطعة‬\n      ‫حشــيش يف ســيارته ولكــن ال يعلــم عنهــا شيء‪.‬وبســماع أقوالــه األوليــة‬\n      ‫اقــر بأنــه يتعاطــى احلشــيش املخــدر منــذ أربعــة أشــهر وانتهــى التحقيــق‬\n      ‫إلــى توجيــه االتهــام ل ـ بحيازتــه لقطعــة تــزن (‪ )0.4‬أربعــة مــن العشــرة‬\n      ‫مــن احلشــيش املخــدر احملظــور لقصــد التعاطــي تعاطــي احلشــيش املخــدر‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة‪ ]1[ :‬مــا جــاء يف محضــر إيضاحــات‬\n      ‫واقعــة القبــض املنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪ )11‬واملرفــق‬\n      ‫علــى اللفــة رقــم (‪ ]2[ )1‬مــا جــاء يف أقوالــه حتقيقـ ًا املنــوه عنهــا و املرفقــة‬\n      ‫علــى للفتني(‪)10-9‬والصفحــة رقــم (‪ )14‬مــن ملــف ضبــط إجــراءات‬\n      ‫اســتدالل لفــة رقــم (‪ ]3[ )1‬التقريــر الكيمــاوي الشــرعي املرفــق صــورة‬\n      ‫منــه علــى اللفــة رقــم (‪ )17‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه‬\n      ‫علــى ســابقة ترويــج مخــدرات ومقاومــة رجــال األمــن وحيــث إن مــا أقــدم‬\n      ‫عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب التالــي‪ :‬أوالً‪ :‬إثبــات مــا ُأســند إليــه‬\n      ‫وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪289‬‬\n\f‫واحلكــم عليــه باآلتــي‪ ]1[ :‬احلكــم عليــه بالســجن وفق ـ ًا للفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة رقــم (‪ )41‬مــن ذات النظــام [‪ ]2‬منعــه مــن الســفر وفق ـ ًا‬\n‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n‫ثانيـاً‪ :‬احلكــم عليــه باملقتضــى الشــرعي لقــاء تعاطيــه احلشــيش املخــدر‬\n‫وبــاهلل التوفيــق هــذا وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام غيــر صحيــح و الصحيــح أنــه مت اســتيقايف مــن قبــل‬\n‫رجــال مكافحــة املخــدرات و قامــوا بتفتيشــي شــخصيا فلــم يتــم العثــور‬\n‫علــى أي شــيء مــن املمنوعــات بحيازتــي ثــم قامــوا بتفتيــش ســيارتي فتــم‬\n‫العثــور بداخــل الســيارة علــى قطعــة احلشــيش املخــدر التــي وزنهــا كمــا‬\n‫هــو مبــن بالئحــة الدعــوى و هــي ال تعــود لــي و ال أعلــم مــن وضعهــا‬\n‫بســيارتي و هــي ال تعــود لــي نهائيــا كمــا أنــي لــم اســتخدم احلشــيش‬\n‫املخــدر بعــد احلكــم علــي مــن فضيلتكــم مبوجــب القــرار الشــرعي‬\n‫رقــم ‪ 32205313‬يف ‪1432 /8/16‬ه ـ هكــذا أجــاب هــذا وبتصفــح‬\n‫أوراق املعاملــة جــرى االطــاع علــى اآلتــي‪ ]1[ :‬التقريــر الكيمــاوي‬\n‫الشــرعي رقــم ‪ 1104‬ك ش و املتضمــن إيجابيــة القطعــة ملــادة احلشــيش‬\n‫املخــدر [‪ ]2‬محضــر واقعــة القبــض و الضبــط و التفتيــش لفــة ‪ 1‬صفحــة‬\n‫‪ 11‬و نــص احلاجــة منــه ‪ ،‬وبتفتيــش الســيارة عثــر اجلنــدي أول بالــدرج‬\n‫الواقــع حتــت مقــود الســيارة علــى قطعــة ســمراء اللــون يشــتبه أن تكــون‬\n‫حشــيش مخــدر بلــغ وزنهــا (‪0.4‬جــم)‪ ]3[ ،‬القــرار الشــرعي الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 32205313‬يف ‪1432 /8/16‬ه ـ و املتضمــن حــد‬\n‫املدعــى عليــه بحــد املســكر بجلــده ثمانــن جلــدة دفعــة واحــدة و تعزيــره‬\n‫علــى احليــازة بســجنه ســتة أشــهر علمــا أن احلكــم لــم يكتســب القطعيــة‬\n‫هــذا وبطلبــي مــن املدعــي العــام زيــادة بينــة قــال ليــس لــدي ســوى مــا‬\n\n\n                                                                                   ‫‪290‬‬\n\f      ‫يف أوراق املعاملــة هكــذا قــرر هــذا وبنــاء علــى املــادة (‪ )159‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة و نصهــا ‪،‬ال تتقيــد احملكمــة بالوصــف الــوارد يف‬\n      ‫الئحــة الدعــوى وعليهــا أن تعطــي الفعــل الوصــف الــذي يســتحقه ولــو‬\n      ‫كان مخالف ـ ًا للوصــف الــوارد يف الئحــة الدعــوى وإذا جــرى التعديــل‬\n      ‫وجــب علــى احملكمــة أن تبلــغ املتهــم بذلــك‪ ،‬و حيــث أن املدعــى عليــه‬\n      ‫أنكــر تعاطيــه للحشــيش املخــدر و أقــر بالعثــور علــى قطعــة احلشــيش‬\n      ‫املخــدر يف ســيارته و قــرر أنــه ال يعلــم عنهــا شــيئا و حيــث أن اإلنســان‬\n      ‫مســئول عمــا حتــت يــده مــن متــاع و ســيارة و نحوهــم و حيــث أن املدعــى‬\n      ‫عليــه لــم يقــر بقصــد االســتعمال يف حيــازة قطعــة احلشــيش املخــدر و‬\n      ‫حيــث أن القصــد مــن أعمــال القلــوب التــي ال تثبــت إال بإقــرار أو بينــة‬\n      ‫دالــة عليــه فــا ينســب للمدعــى عليــه قصــد لــم يقــر بــه ولــم تقــم بينــة‬\n      ‫عليــه لــذا وبنــاء علــى املــادة (‪ )39‬مــن نظــام مكافحــة املخــدرات و‬\n      ‫املؤثــرات العقليــة ونصهــا ‪،‬يعاقــب بالســجن مــدة ال تقــل عــن ســنتني وال‬\n      ‫تزيــد علــى خمــس ســنوات ‪ ،‬وباجللــد مبــا ال يزيــد علــى خمســن جلــدة‬\n      ‫يف كل مــرة‪ ،‬وبغرامــة ال تقــل عــن ثالثــة آالف ريــال وال تزيــد علــى‬\n      ‫ثالثــن ألــف ريــال‪ ،‬كل مــن حــاز مــواد مخــدرة أو مؤثــرات عقليــة أو‬\n      ‫أحرزهــا أو نقلهــا أو ســلمها أو تســلمها لغيــر قصــد االجتــار أو الترويــج‬\n      ‫أو التعاطــي أو االســتعمال الشــخصي ‪ ،‬وذلــك يف غيــر األحــوال املرخص‬\n      ‫بهــا يف هــذا النظــام ‪ ،‬فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة قطعــة‬\n      ‫ـدي‬\n       ‫حشــيش مخــدر بلــغ وزنهــا أربعــة بالعشــرة مــن اجلــرام ولــم يثبــت لـ َّ‬\n      ‫شــرعا قصــد املدعــى عليــه مــن هــذه احليــازة لعــدم كفايــة األدلــة كمــا‬\n      ‫لــم يثبــت لــدي شــرعا إدانتــه بتعاطــي احلشــيش املخــدر و بنــاء علــى املــادة‬\n      ‫(‪ )60‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة فقــد قــررت‬\n\n\n‫‪291‬‬\n\f‫النــزول عــن احلــد األدنــى وذلــك نظــرا لقلــة كميــة املــادة املضبوطــة‬\n‫بحيازتــه و حكمــت عليــه باآلتــي [‪ ]1‬تعزيــره علــى احليــازة املجــردة وفقــا‬\n‫للمــادة (‪ )39‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة مــع‬\n‫مراعــاة النــزول عــن احلــد األدنــى نظــرا لقلــة كميــة املــادة املضبوطــة‬\n‫بحيازتــه بســجنه ســتة أشــهر تبــدأ اعتبــارا مــن تاريــخ توقيفــه و جلــده‬\n‫خمســن جلــدة دفعــة واحــدة علنــا و يف مــكان عــام و تغرميــه ألفــي ريــال‬\n‫تــودع يف خزينــة الدولــة و تصــرف يف املصــارف العامــة [‪ ]2‬منعــه مــن‬\n‫الســفر وفقــا للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام مــدة ســنتني تبــدأ‬\n‫اعتبــارا مــن خروجــه مــن الســجن [‪ ]3‬رد مطالبــة املدعــي العــام مبعاقبــة‬\n‫املدعــى عليــه وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n‫املخــدرات وذلــك لعــدم انطباقهــا علــى املدعــى عليــه [‪ ]4‬رد مطالبــة‬\n‫املدعــي العــام باحلكــم علــى املدعــى عليــه باملقتضــى الشــرعي لقــاء‬\n‫تعاطيــه للحشــيش املخــدر لعــدم ثبــوت التعاطــي وبعــرض احلكــم عليهــم‬\n‫قــرر املدعــي العــام املعارضــة وقــرر اكتفائــه بالئحــة الدعــوى عــن تقــدمي‬\n‫الئحــة معارضــة وقــرر املدعــى عليــه القناعــة باحلكــم وصلــى اهلل علــى‬\n‫نبينــا محمــد و آلــه وصحبــه وســلم حــرر يف ‪1433 /5/11‬ه ـ احلمــد هلل‬\n‫و حــده و بعــد ففــي يــوم األحــد املوافــق ‪1433 /9/3‬ه ـ الســاعة ‪12.30‬‬\n‫افتتحــت اجللســة و فيهــا حضــر املدعــي العــام و حضــر حلضــوره الســجني‬\n‫و قــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم ‪33/1169785‬‬\n‫يف ‪1433 /8/22‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫اجلزائيــة األولــى ـ ـ ـ ـ ـ (ج‪ )1/‬رقــم ‪ 33376269‬يف ‪1433 /8/12‬ه ـ ونــص‬\n‫احلاجــة منــه ‪ ،‬وبدراســة القــرار و صــورة ضبطــه و أوراق املعاملــة لوحــظ‬\n‫أوال‪ :‬أن فضيلــة ناظــر القضيــة حكــم علــى املدعــى عليــه لقــاء احليــازة‬\n\n\n                                                                                         ‫‪292‬‬\n\f      ‫املجــردة بغرامــة قدرهــا ألفــي ريــال يف حــن أن املــادة تنــص علــى أن‬\n      ‫الغرامــة ال تقــل عــن ثالثــة آالف ريــال ثانيــا صــورة الضبــط لــم توقــع‬\n      ‫مــن فضيلتــه وال بــد مــن ذلــك ‪ ،‬عليــه أجيــب مبــا يلــي أوال‪ :‬أنــه لوجاهــة‬\n      ‫مــا ذكــره أصحــاب الفضيلــة يف املالحظــة األولــى وبعــد الرجــوع لنــص‬\n      ‫املــادة التاســعة و الثالثــن فقــد حكمــت بزيــادة الغرامــة علــى املدعــى‬\n      ‫عليــه لتكــون بعــد الزيــادة مبلغــا وقــدره ثالثــة آالف ريــال ثانيــا‪ :‬أنــه‬\n      ‫مت إجــراء الــازم بالتوقيــع علــى صــورة ضبــط القضيــة هــذا و بعــرض‬\n      ‫ذلــك علــى املدعــى عليــه قــرر القناعــة بــه أمــا املدعــي العــام فقــرر عــدم‬\n      ‫القناعــة مكتفيــا بالئحــة الدعــوى عــن تقــدمي معارضــة وصلــى اهلل علــى‬\n      ‫نبينــا محمــد و آلــه وصحبــه وســلم حــرر يف ‪1433 /9/3‬ه ـ احلمــد هلل‬\n      ‫وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/2/30‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 11.10‬بنــاء علــى ورود املعاملــة مــن محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية برقــم ‪ 332274414‬يف ‪1434/2/12‬ه ـ و برفقهــا‬\n      ‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى برقــم قــرار‬\n      ‫‪ 3428796‬يف ‪1434/2/4‬ه ـ و نــص احلاجــة منــه (حيــث ســبق دراســة‬\n      ‫القــرار وصــورة ضبطــه وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n      ‫وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪/33376269‬‬\n      ‫ج‪/1‬ب يف ‪1433/8/12‬ه ـ لوحــظ ان فضيلتــه لــم يرفــق صــورة الضبــط‬\n      ‫ملــا أجــراه أخيــرا إلكمــال الزم املالحظــة) عليــه أجيــب أصحــاب‬\n      ‫الفضيلــة انــه جــرى إرفــاق صــورة الضبــط وللبيــان جــرى إحلاقــه بضبطــه‬\n      ‫وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق‪.‬‬\n      ‫احلمــد اهلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n\n\n‫‪293‬‬\n\f‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 34388483‬وتاريــخ ‪1434/03/07‬ه ـ املقيــد لــدى احملكمــة برقــم‬\n‫‪/588688/34‬ج‪ 1‬وتاريــخ ‪1434/03/08‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ .....‬املســجل برقــم ‪33275897‬‬\n‫وتاريــخ ‪1433/06/01‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ .....‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه حيــث ســبق دراســة القــرار وصــورة ضبطــه وباإلطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبــط بنــاء علــى‬\n‫قرارنــا رقــم ‪/3428796‬ج‪/1‬ب يف ‪1434/02/04‬ه ـ قررنــا املصادقــة‬\n‫علــى احلكــم بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/13‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪294‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":287,"source_page_end":294,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83bbf26b56a3e9c6876d82ac38c0ffd5b35f9dc64da6fc02ea6b913235e91ecf","normalized_text_hash":"9df9b51da33d6816d3992624bad3c71308b53b3be4863e3c125b9293caf910c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p287-33275897"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

